--
-- Name: apply_inventory_movement(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."apply_inventory_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.product_stock (product_id)
  values (new.product_id)
  on conflict (product_id) do nothing;

  if new.movement_type in ('reservation', 'reservation_release') then
    update public.product_stock
    set reserved = reserved + new.units, updated_at = now()
    where product_id = new.product_id;
  else
    update public.product_stock
    set on_hand = on_hand + new.units, updated_at = now()
    where product_id = new.product_id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."apply_inventory_movement"() OWNER TO "postgres";

--
-- Name: apply_staff_invitation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."apply_staff_invitation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_invitation public.staff_invitations;
  v_token text := new.raw_user_meta_data ->> 'staff_invite_token';
begin
  if v_token is null then
    return new;
  end if;
  -- The code is used once and never stays in the session token.
  new.raw_user_meta_data := new.raw_user_meta_data - 'staff_invite_token';
  select * into v_invitation from public.staff_invitations
  where email = lower(trim(new.email)) and status = 'pending' and expires_at > now()
    and token_hash = encode(extensions.digest(v_token, 'sha256'), 'hex');
  if v_invitation.id is not null then
    new.raw_app_meta_data := coalesce(new.raw_app_meta_data, '{}'::jsonb)
      || jsonb_build_object('staff_role', v_invitation.staff_role);
    new.raw_user_meta_data := coalesce(new.raw_user_meta_data, '{}'::jsonb)
      || jsonb_build_object('full_name', v_invitation.full_name);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."apply_staff_invitation"() OWNER TO "postgres";

