    CONSTRAINT "payment_attempts_refund_only_approved" CHECK (((NOT "refund_needed") OR ("status" = 'approved'::"public"."payment_attempt_status"))),
    CONSTRAINT "payment_attempts_refund_reason_check" CHECK (("refund_reason" = 'duplicate_payment'::"text")),
    CONSTRAINT "payment_attempts_refund_reason_pair" CHECK (("refund_needed" = ("refund_reason" IS NOT NULL))),
    CONSTRAINT "payment_attempts_refund_reference_check" CHECK ((("refund_reference" IS NULL) OR (("length"(TRIM(BOTH FROM "refund_reference")) >= 3) AND ("length"(TRIM(BOTH FROM "refund_reference")) <= 120)))),
    CONSTRAINT "payment_attempts_refunded_needed" CHECK ((("refunded_at" IS NULL) OR "refund_needed")),
    CONSTRAINT "payment_attempts_refunded_trio" CHECK (((("refunded_at" IS NULL) = ("refund_reference" IS NULL)) AND (("refunded_at" IS NULL) = ("refund_note" IS NULL)))),
    CONSTRAINT "payment_attempts_transaction_id_hint_check" CHECK (("transaction_id_hint" ~ '^[0-9A-Za-z-]{6,64}$'::"text"))
);


