--
-- Name: can_upload_delivery_signature("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."can_upload_delivery_signature"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_parts text[] := string_to_array(p_name, '/');
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
begin
  if coalesce(array_length(v_parts, 1), 0) <> 2
     or v_parts[1] !~ (v_uuid || '$')
     or v_parts[2] !~ (v_uuid || '\.png$') then
    return false;
  end if;
  return private.can_deliver_order(v_parts[1]::uuid);
end;
$_$;


