--
-- Name: cancel_web_order("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."cancel_web_order"("p_order_id" "uuid", "p_reason" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.orders
  set status = 'cancelled', cancelled_at = now(), cancel_reason = p_reason
  where id = p_order_id and status = 'awaiting_payment';
  if not found then
    return false;
  end if;
  perform private.release_reservations(p_order_id::text, 'released', false);
  return true;
end;
$$;


