--
-- Name: close_attempt_without_payment("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."close_attempt_without_payment"("p_attempt_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.payment_attempts pa
  set status = 'abandoned', finalized_at = now()
  from public.orders o
  where pa.id = p_attempt_id
    and o.id = pa.order_id
    and o.status <> 'awaiting_payment'
    and pa.status = 'pending'
    and pa.wompi_transaction_id is null
    and pa.transaction_id_hint is null;
$$;


