--
-- Name: close_attempts_of_cancelled_order(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."close_attempts_of_cancelled_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'cancelled' and old.status is distinct from 'cancelled' then
    -- Attempts with a real transaction stay pending: if Wompi approves them
    -- later, apply_payment_event flags the order for refund.
    update public.payment_attempts
    set status = 'abandoned', finalized_at = now()
    where order_id = new.id and status = 'pending'
      and wompi_transaction_id is null and transaction_id_hint is null;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."close_attempts_of_cancelled_order"() OWNER TO "postgres";

--
-- Name: create_customer_profile(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_customer_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_type public.customer_type;
  v_version text := trim(m ->> 'legal_version');
  v_nit text;
begin
  if private.is_server_provisioned(new.raw_app_meta_data) then
    return null;
  end if;

  v_type := (m ->> 'customer_type')::public.customer_type;
  v_nit := nullif(replace(m ->> 'nit', '-', ''), '');

  insert into public.customers (
    id, customer_type, wholesale_status, full_name, business_name,
    document_type, document_number, phone
  ) values (
    new.id,
    v_type,
    case when v_type = 'wholesale' then 'pending'::public.wholesale_status end,
    trim(m ->> 'full_name'),
    case when v_type = 'wholesale' then trim(m ->> 'business_name') end,
    case when v_type = 'wholesale' then 'nit'::public.document_type end,
    case when v_type = 'wholesale' then v_nit end,
    nullif(trim(m ->> 'phone'), '')
  );

  insert into public.legal_acceptances (user_id, document, version, declared_birth_date)
  values
    (new.id, 'age_gate', v_version, (m ->> 'birth_date')::date),
    (new.id, 'terms', v_version, null),
    (new.id, 'privacy', v_version, null);

  -- The birth date and NIT now live only in the audit and customers tables;
  -- user_metadata is copied into every session token.
  update auth.users
  set raw_user_meta_data = raw_user_meta_data
    - 'birth_date' - 'nit' - 'accept_age' - 'accept_terms' - 'accept_privacy'
  where id = new.id;

  return null;
end;
$$;


ALTER FUNCTION "private"."create_customer_profile"() OWNER TO "postgres";

--
-- Name: create_payment_attempt("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_payment_attempt"("p_order_id" "uuid", "p_customer_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.orders;
  v_action_id uuid;
  v_existing public.actions;
  v_open public.payment_attempts;
  v_attempt public.payment_attempts;
  v_number integer;
  v_ttl integer := private.setting_integer('reservation_ttl_minutes', 30);
  v_items jsonb;
begin
  -- Same key, same answer (double click, two tabs).
  insert into public.actions (idempotency_key, type, user_id, status, payload, attempts, started_at)
  values (p_idempotency_key, 'start_payment', p_customer_id, 'processing',
          jsonb_build_object('order_id', p_order_id), 1, now())
  on conflict (idempotency_key) do nothing
  returning id into v_action_id;

  if v_action_id is null then
    select * into v_existing from public.actions where idempotency_key = p_idempotency_key;
    if v_existing.user_id is distinct from p_customer_id or v_existing.type <> 'start_payment' then
      raise exception 'idempotency_key_conflict' using errcode = 'P0001';
    end if;
    select * into v_attempt from public.payment_attempts
    where id = (v_existing.result ->> 'attempt_id')::uuid;
    return jsonb_build_object('ok', true, 'tracking_id', v_existing.id, 'attempt', to_jsonb(v_attempt));
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status <> 'awaiting_payment' then
    raise exception 'payment_order_not_payable' using errcode = '22023';
  end if;

  select * into v_open from public.payment_attempts
  where order_id = p_order_id and status = 'pending' for update;

  if v_open.id is not null then
    if v_open.wompi_transaction_id is not null or v_open.transaction_id_hint is not null then
      -- A real transaction is in progress (e.g. PSE): wait for its answer.
      raise exception 'payment_in_progress' using errcode = '22023';
    end if;
    -- The customer never paid with the previous attempt: replace it.
    update public.payment_attempts
    set status = 'abandoned', finalized_at = now()
    where id = v_open.id;
  end if;

  -- The stock reservation expired (30 min) but the order is still open:
  -- reserve again before paying. Fails if the stock is gone.
  if not exists (
    select 1 from public.stock_reservations
    where reference = p_order_id::text and status = 'active'
  ) then
    select jsonb_agg(jsonb_build_object('product_id', product_id, 'units', base_units))
    into v_items
    from public.order_items where order_id = p_order_id;
    perform private.reserve_units(p_order_id::text, v_items, v_ttl, p_customer_id);
    update public.orders
    set payment_deadline = now() + make_interval(mins => v_ttl)
    where id = p_order_id
    returning * into v_order;
  end if;

  select coalesce(max(attempt_number), 0) + 1 into v_number
  from public.payment_attempts where order_id = p_order_id;

  insert into public.payment_attempts (
    order_id, attempt_number, reference, amount_in_cents, expires_at, idempotency_key
  ) values (
    p_order_id,
    v_number,
    -- Short, unique and traceable to the order.
    upper(replace(p_order_id::text, '-', '')) || '-' || v_number,
    v_order.total_cop * 100,
    v_order.payment_deadline,
    p_idempotency_key
  )
  returning * into v_attempt;

  update public.actions
  set status = 'succeeded', result = jsonb_build_object('attempt_id', v_attempt.id), finished_at = now()
  where id = v_action_id;

  return jsonb_build_object('ok', true, 'tracking_id', v_action_id, 'attempt', to_jsonb(v_attempt));
end;
$$;


ALTER FUNCTION "private"."create_payment_attempt"("p_order_id" "uuid", "p_customer_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: create_pos_order("uuid", "jsonb", "text", bigint, "uuid", boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_pos_order"("p_idempotency_key" "uuid", "p_items" "jsonb", "p_payment_method" "text", "p_cash_received_cop" bigint, "p_customer_id" "uuid", "p_age_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cashier uuid := auth.uid();
  v_action_id uuid;
  v_existing public.actions;
  v_quote jsonb;
  v_order_id uuid;
  v_total bigint;
  v_line jsonb;
  v_stock public.product_stock;
  v_units integer;
  v_product_id uuid;
begin
  perform private.require_pos_staff();

  insert into public.actions (idempotency_key, type, user_id, status, payload, attempts, started_at)
  values (p_idempotency_key, 'pos_sale', v_cashier, 'processing',
          jsonb_build_object('payment_method', p_payment_method, 'customer_id', p_customer_id), 1, now())
  on conflict (idempotency_key) do nothing
  returning id into v_action_id;

  if v_action_id is null then
    select * into v_existing from public.actions where idempotency_key = p_idempotency_key;
    if v_existing.user_id is distinct from v_cashier or v_existing.type <> 'pos_sale' then
      raise exception 'idempotency_key_conflict' using errcode = 'P0001';
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'tracking_id', v_existing.id,
                              'order_id', v_existing.result ->> 'order_id');
  end if;

  if p_age_confirmed is distinct from true then
    raise exception 'pos_age_not_confirmed' using errcode = '22023';
  end if;
  if p_payment_method is null or p_payment_method not in ('cash', 'card', 'transfer') then
    raise exception 'pos_invalid_payment_method' using errcode = '22023';
  end if;

  v_quote := private.pos_quote(p_items, p_customer_id);
  if v_quote is null then
    raise exception 'pos_customer_not_found' using errcode = '22023';
  end if;
  if not (v_quote ->> 'ok')::boolean then
    raise exception 'pos_quote_failed' using errcode = '22023', detail = v_quote::text;
  end if;
  v_total := (v_quote ->> 'total_cop')::bigint;
  if p_payment_method = 'cash' and (p_cash_received_cop is null or p_cash_received_cop < v_total) then
    raise exception 'pos_cash_insufficient' using errcode = '22023',
      detail = jsonb_build_object('total_cop', v_total)::text;
  end if;

  -- The sales-block trigger (step 15) runs here and may reject the sale.
  insert into public.orders (
    customer_id, channel, status, fulfillment, sale_unit,
    subtotal_cop, delivery_fee_cop, total_cop, total_boxes, total_base_units,
    idempotency_key, paid_at, delivered_at,
    cashier_id, pos_payment_method, cash_received_cop, change_cop, age_confirmed
  ) values (
    p_customer_id, 'pos', 'delivered', 'pickup', v_quote ->> 'sale_unit',
    v_total, 0, v_total, (v_quote ->> 'total_boxes')::integer, (v_quote ->> 'total_base_units')::integer,
    p_idempotency_key, now(), now(),
    v_cashier, p_payment_method,
    case when p_payment_method = 'cash' then p_cash_received_cop end,
    case when p_payment_method = 'cash' then p_cash_received_cop - v_total end,
    p_age_confirmed
  )
  returning id into v_order_id;

  for v_line in select value from jsonb_array_elements(v_quote -> 'lines')
  loop
    insert into public.order_items (
      order_id, product_id, sku, product_name, sale_unit, units_per_box,
      quantity, unit_price_cop, line_total_cop, base_units
    )
    select
      v_order_id, p.id, p.sku, p.name, v_quote ->> 'sale_unit', p.units_per_box,
      (v_line ->> 'quantity')::integer, (v_line ->> 'unit_price_cop')::bigint,
      (v_line ->> 'line_total_cop')::bigint, (v_line ->> 'base_units')::integer
    from public.products p
    where p.id = (v_line ->> 'product_id')::uuid;
  end loop;

  -- Stock, in product order to avoid deadlocks. Only what is available:
  -- units reserved for pending web orders are never sold (D-038).
  for v_line in
    select value from jsonb_array_elements(v_quote -> 'lines') order by value ->> 'product_id'
  loop
    v_product_id := (v_line ->> 'product_id')::uuid;
    v_units := (v_line ->> 'base_units')::integer;
    v_stock := private.lock_stock(v_product_id);
    if v_stock.on_hand - v_stock.reserved < v_units then
      raise exception 'inventory_insufficient_stock' using errcode = '22023',
        detail = jsonb_build_object('product_id', v_product_id,
                                    'available_units', greatest(v_stock.on_hand - v_stock.reserved, 0))::text;
    end if;
    insert into public.inventory_movements
      (product_id, movement_type, units, reference, created_by, idempotency_key)
    values
      (v_product_id, 'pos_sale', -v_units, v_order_id::text, v_cashier,
       private.uuid_from_text('pos_sale:' || v_order_id || ':' || v_product_id));
  end loop;

  -- Same key as the web trigger: one invoice per order.
  perform public.enqueue_action(
    private.uuid_from_text('issue_invoice:' || v_order_id::text),
    'issue_invoice', null, jsonb_build_object('order_id', v_order_id), 8
  );

  update public.actions
  set status = 'succeeded', result = jsonb_build_object('order_id', v_order_id), finished_at = now()
  where id = v_action_id;

  return jsonb_build_object('ok', true, 'created', true, 'tracking_id', v_action_id, 'order_id', v_order_id);
end;
$$;


ALTER FUNCTION "private"."create_pos_order"("p_idempotency_key" "uuid", "p_items" "jsonb", "p_payment_method" "text", "p_cash_received_cop" bigint, "p_customer_id" "uuid", "p_age_confirmed" boolean) OWNER TO "postgres";

--
-- Name: create_web_order("uuid", "public"."fulfillment_method", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_web_order"("p_idempotency_key" "uuid", "p_fulfillment" "public"."fulfillment_method", "p_address_id" "uuid", "p_pickup_document" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_customer_id uuid := auth.uid();
  v_action_id uuid;
  v_existing public.actions;
  v_items jsonb;
  v_quote jsonb;
  v_order_id uuid := gen_random_uuid();
  v_ttl integer;
  v_window integer;
  v_line jsonb;
  v_reserve jsonb := '[]'::jsonb;
  v_delivery jsonb;
  v_fee bigint := 0;
  v_subtotal bigint;
  v_document text;
begin
  -- Who: only the signed-in customer, for their own cart.
  if v_customer_id is null or not exists (select 1 from public.customers where id = v_customer_id) then
    raise exception 'order_requires_customer' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'order_missing_idempotency_key' using errcode = '22023';
  end if;

  -- A retry of an order already placed returns it, even with an empty cart.
  select * into v_existing from public.actions where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.user_id is distinct from v_customer_id or v_existing.type <> 'place_order' then
      raise exception 'idempotency_key_conflict' using errcode = 'P0001';
    end if;
    return jsonb_build_object(
      'ok', true, 'created', false,
      'tracking_id', v_existing.id,
      'order_id', v_existing.result ->> 'order_id'
    );
  end if;

  -- What and at what price: the cart and the quote are computed here, never
  -- received (agents.md §5.1).
  v_items := public.get_cart_items();
  if jsonb_array_length(v_items) = 0 then
    return jsonb_build_object('ok', false, 'error', 'cart_empty');
  end if;
  v_quote := public.quote_items(v_items);
  if not (v_quote ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', 'quote_failed', 'quote', v_quote);
  end if;
  v_subtotal := (v_quote ->> 'total_cop')::bigint;

  -- Pickup (D-059): customers without a registered NIT say whose cédula will
  -- pick the order up. Customers with a NIT confirm with it.
  if p_fulfillment = 'pickup' and not exists (
    select 1 from public.customers where id = v_customer_id and document_type = 'nit'
  ) then
    if nullif(btrim(coalesce(p_pickup_document, '')), '') is null then
      return jsonb_build_object('ok', false, 'error', 'pickup_document_required');
    end if;
    v_document := private.normalize_id_document(p_pickup_document);
    if v_document is null then
      return jsonb_build_object('ok', false, 'error', 'invalid_pickup_document');
    end if;
  end if;

  -- Layer 3 of idempotency: the action key is UNIQUE. A concurrent second
  -- call waits here for the first one and then returns its result. The
  -- document is never stored in the payload.
  insert into public.actions (idempotency_key, type, user_id, status, payload, attempts, started_at)
  values (p_idempotency_key, 'place_order', v_customer_id, 'processing',
          jsonb_build_object('fulfillment', p_fulfillment, 'address_id', p_address_id), 1, now())
  on conflict (idempotency_key) do nothing
  returning id into v_action_id;

  if v_action_id is null then
    select * into v_existing from public.actions where idempotency_key = p_idempotency_key;
    if v_existing.user_id is distinct from v_customer_id or v_existing.type <> 'place_order' then
      raise exception 'idempotency_key_conflict' using errcode = 'P0001';
    end if;
    return jsonb_build_object(
      'ok', true, 'created', false,
      'tracking_id', v_existing.id,
      'order_id', v_existing.result ->> 'order_id'
    );
  end if;

  -- After the role and idempotency checks (D-056: nothing costly before them).
  v_ttl := private.setting_integer('reservation_ttl_minutes', 30);
  v_window := private.setting_integer('order_payment_window_hours', 24);

  if p_fulfillment = 'delivery' then
    -- The fee is always computed here, never received (agents.md §5.1).
    v_delivery := private.delivery_quote(
      p_address_id, v_customer_id, v_quote ->> 'sale_unit', (v_quote ->> 'total_boxes')::integer
    );
    if not (v_delivery ->> 'ok')::boolean then
      raise exception 'order_delivery_unavailable'
        using errcode = '22023', detail = v_delivery ->> 'error';
    end if;
    v_fee := (v_delivery ->> 'fee_cop')::bigint;
  end if;

  insert into public.orders (
    id, customer_id, channel, status, fulfillment, sale_unit,
    subtotal_cop, delivery_fee_cop, total_cop, total_boxes, total_base_units,
    idempotency_key, payment_deadline, cancel_after,
    delivery_address, delivery_distance_m
  ) values (
    v_order_id, v_customer_id, 'web', 'awaiting_payment', p_fulfillment, v_quote ->> 'sale_unit',
    v_subtotal, v_fee, v_subtotal + v_fee,
    (v_quote ->> 'total_boxes')::integer, (v_quote ->> 'total_base_units')::integer,
    p_idempotency_key, now() + make_interval(mins => v_ttl), now() + make_interval(hours => v_window),
    v_delivery -> 'address', (v_delivery ->> 'distance_m')::integer
  );

  if p_fulfillment = 'pickup' then
    insert into private.order_pickup_documents (order_id, document_hash, document_last3)
    values (
      v_order_id,
      case when v_document is not null then private.pickup_document_hash(v_order_id, v_document) end,
      case when v_document is not null then right(v_document, 3) end
    );
  end if;

  for v_line in select value from jsonb_array_elements(v_quote -> 'lines')
  loop
    insert into public.order_items (
      order_id, product_id, sku, product_name, sale_unit, units_per_box,
      quantity, unit_price_cop, line_total_cop, base_units
    )
    select
      v_order_id, p.id, p.sku, p.name, v_quote ->> 'sale_unit', p.units_per_box,
      (v_line ->> 'quantity')::integer, (v_line ->> 'unit_price_cop')::bigint,
      (v_line ->> 'line_total_cop')::bigint, (v_line ->> 'base_units')::integer
    from public.products p
    where p.id = (v_line ->> 'product_id')::uuid;

    v_reserve := v_reserve || jsonb_build_object(
      'product_id', v_line ->> 'product_id',
      'units', (v_line ->> 'base_units')::integer
    );
  end loop;

  -- All or nothing: an insufficient stock error aborts the whole order.
  perform private.reserve_units(v_order_id::text, v_reserve, v_ttl, v_customer_id);

  delete from public.cart_items
  where cart_id = (select id from public.carts where customer_id = v_customer_id);

  update public.actions
  set status = 'succeeded',
      result = jsonb_build_object('order_id', v_order_id),
      finished_at = now()
  where id = v_action_id;

  return jsonb_build_object(
    'ok', true, 'created', true,
    'tracking_id', v_action_id,
    'order_id', v_order_id
  );
end;
$$;


ALTER FUNCTION "private"."create_web_order"("p_idempotency_key" "uuid", "p_fulfillment" "public"."fulfillment_method", "p_address_id" "uuid", "p_pickup_document" "text") OWNER TO "postgres";

--
-- Name: orders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid",
    "channel" "public"."order_channel" NOT NULL,
    "status" "public"."order_status" DEFAULT 'awaiting_payment'::"public"."order_status" NOT NULL,
    "fulfillment" "public"."fulfillment_method" NOT NULL,
    "sale_unit" "text" NOT NULL,
    "subtotal_cop" bigint NOT NULL,
    "delivery_fee_cop" bigint DEFAULT 0 NOT NULL,
    "total_cop" bigint NOT NULL,
    "total_boxes" integer DEFAULT 0 NOT NULL,
    "total_base_units" integer NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "payment_deadline" timestamp with time zone,
    "cancel_after" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancel_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "needs_refund" boolean DEFAULT false NOT NULL,
    "refund_reason" "text",
    "delivery_address" "jsonb",
    "delivery_distance_m" integer,
    "delivery_provider_id" "uuid",
    "courier_id" "uuid",
    "delivery_external_ref" "text",
    "assigned_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "sale_zone_id" "uuid",
    "cashier_id" "uuid",
    "pos_payment_method" "text",
    "cash_received_cop" bigint,
    "change_cop" bigint,
    "age_confirmed" boolean,
    "voided_at" timestamp with time zone,
    "void_reason" "text",
    "voided_by" "uuid",
    "refunded_at" timestamp with time zone,
    "refunded_by" "uuid",
    "refund_reference" "text",
    "refund_note" "text",
    "delivery_return_kind" "text",
    "returned_at" timestamp with time zone,
    "return_choice" "text",
    "return_choice_at" timestamp with time zone,
    "return_choice_deadline" timestamp with time zone,
    "return_choice_defaulted" boolean DEFAULT false NOT NULL,
    "scheduled_delivery_on" "date",
    "refund_amount_cop" bigint,
    CONSTRAINT "orders_cancelled_check" CHECK ((("status" = 'cancelled'::"public"."order_status") = ("cancelled_at" IS NOT NULL))),
    CONSTRAINT "orders_cash_check" CHECK ((("pos_payment_method" IS DISTINCT FROM 'cash'::"text") OR (("cash_received_cop" >= "total_cop") AND ("change_cop" = ("cash_received_cop" - "total_cop"))))),
    CONSTRAINT "orders_cash_received_cop_check" CHECK (("cash_received_cop" >= 0)),
    CONSTRAINT "orders_change_cop_check" CHECK (("change_cop" >= 0)),
    CONSTRAINT "orders_delivery_address_check" CHECK ((("fulfillment" <> 'delivery'::"public"."fulfillment_method") OR (("delivery_address" IS NOT NULL) AND ("delivery_distance_m" IS NOT NULL)))),
    CONSTRAINT "orders_delivery_distance_m_check" CHECK (("delivery_distance_m" >= 0)),
    CONSTRAINT "orders_delivery_external_ref_check" CHECK ((("delivery_external_ref" IS NULL) OR ("length"("delivery_external_ref") <= 100))),
    CONSTRAINT "orders_delivery_fee_cop_check" CHECK (("delivery_fee_cop" >= 0)),
    CONSTRAINT "orders_delivery_return_kind_check" CHECK (("delivery_return_kind" = ANY (ARRAY['customer'::"text", 'force_majeure'::"text", 'underage'::"text"]))),
    CONSTRAINT "orders_pos_check" CHECK ((("channel" <> 'pos'::"public"."order_channel") OR (("cashier_id" IS NOT NULL) AND ("pos_payment_method" IS NOT NULL) AND ("age_confirmed" IS TRUE)))),
    CONSTRAINT "orders_pos_payment_method_check" CHECK (("pos_payment_method" = ANY (ARRAY['cash'::"text", 'card'::"text", 'transfer'::"text"]))),
    CONSTRAINT "orders_refund_amount_cop_check" CHECK (("refund_amount_cop" > 0)),
    CONSTRAINT "orders_refund_amount_needs_refund_check" CHECK ((("refund_amount_cop" IS NULL) OR ("needs_refund" AND ("refund_amount_cop" <= "total_cop")))),
    CONSTRAINT "orders_refund_note_check" CHECK ((("refund_note" IS NULL) OR (("length"(TRIM(BOTH FROM "refund_note")) >= 3) AND ("length"(TRIM(BOTH FROM "refund_note")) <= 300)))),
    CONSTRAINT "orders_refund_reason_check" CHECK (("needs_refund" = ("refund_reason" IS NOT NULL))),
    CONSTRAINT "orders_refund_reference_check" CHECK ((("refund_reference" IS NULL) OR (("length"(TRIM(BOTH FROM "refund_reference")) >= 3) AND ("length"(TRIM(BOTH FROM "refund_reference")) <= 120)))),
    CONSTRAINT "orders_refunded_check" CHECK (((("refunded_at" IS NULL) = ("refund_reference" IS NULL)) AND (("refunded_at" IS NULL) = ("refund_note" IS NULL)) AND (("refunded_at" IS NULL) OR "needs_refund"))),
    CONSTRAINT "orders_return_choice_check" CHECK (("return_choice" = ANY (ARRAY['pickup'::"text", 'reschedule'::"text", 'refund'::"text"]))),
    CONSTRAINT "orders_return_choice_kind_check" CHECK ((("return_choice" IS NULL) OR ("delivery_return_kind" = 'customer'::"text"))),
    CONSTRAINT "orders_return_choice_pair_check" CHECK ((("return_choice" IS NULL) = ("return_choice_at" IS NULL))),
    CONSTRAINT "orders_return_deadline_check" CHECK ((("return_choice_deadline" IS NOT NULL) = (NOT ("delivery_return_kind" IS DISTINCT FROM 'customer'::"text")))),
    CONSTRAINT "orders_return_defaulted_check" CHECK (((NOT "return_choice_defaulted") OR ("return_choice" = 'pickup'::"text"))),
    CONSTRAINT "orders_return_kind_pair_check" CHECK ((("delivery_return_kind" IS NULL) = ("returned_at" IS NULL))),
    CONSTRAINT "orders_sale_unit_check" CHECK (("sale_unit" = ANY (ARRAY['unit'::"text", 'box'::"text"]))),
    CONSTRAINT "orders_subtotal_cop_check" CHECK (("subtotal_cop" > 0)),
    CONSTRAINT "orders_total_base_units_check" CHECK (("total_base_units" > 0)),
    CONSTRAINT "orders_total_boxes_check" CHECK (("total_boxes" >= 0)),
    CONSTRAINT "orders_total_check" CHECK (("total_cop" = ("subtotal_cop" + "delivery_fee_cop"))),
    CONSTRAINT "orders_void_check" CHECK ((("voided_at" IS NULL) = ("void_reason" IS NULL))),
    CONSTRAINT "orders_void_reason_check" CHECK ((("void_reason" IS NULL) OR (("length"(TRIM(BOTH FROM "void_reason")) >= 3) AND ("length"(TRIM(BOTH FROM "void_reason")) <= 300)))),
    CONSTRAINT "orders_web_customer_check" CHECK ((("channel" <> 'web'::"public"."order_channel") OR ("customer_id" IS NOT NULL)))
);


