  if new.status = 'paid' and old.status is distinct from 'paid' and not new.needs_refund then
    perform public.enqueue_action(
      private.uuid_from_text('issue_invoice:' || new.id::text),
      'issue_invoice',
      null,
      jsonb_build_object('order_id', new.id),
      8
    );
  end if;
  return null;
end;
$$;


