--
-- Name: inventory_movement_for_key("uuid", "uuid", "public"."inventory_movement_type"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."inventory_movement_for_key"("p_key" "uuid", "p_product_id" "uuid", "p_type" "public"."inventory_movement_type") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_row public.inventory_movements;
begin
  if p_key is null then
    perform private.inventory_error('missing_idempotency_key');
  end if;
  select * into v_row from public.inventory_movements where idempotency_key = p_key;
  if v_row.id is null then
    return null;
  end if;
  if v_row.product_id <> p_product_id
     or v_row.movement_type <> p_type
     or v_row.created_by is distinct from auth.uid() then
    perform private.inventory_error('idempotency_key_conflict');
  end if;
  return v_row.id;
end;
$$;


