--
-- Name: invoke_actions_worker(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."invoke_actions_worker"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url
  from vault.decrypted_secrets where name = 'actions_worker_url';
  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name = 'actions_worker_secret';

  if v_url is null or v_secret is null then
    return;
  end if;

  if not exists (select 1 from pgmq.q_actions where vt <= now()) then
    return;
  end if;

  perform net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 5000
  );
end;
$$;


ALTER FUNCTION "private"."invoke_actions_worker"() OWNER TO "postgres";

--
-- Name: invoke_payments_reconciliation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."invoke_payments_reconciliation"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url
  from vault.decrypted_secrets where name = 'payments_reconcile_url';
  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name = 'actions_worker_secret';
  if v_url is null or v_secret is null then
    return;
  end if;
  if not exists (
    select 1 from public.payment_attempts
    where status = 'pending' and coalesce(wompi_transaction_id, transaction_id_hint) is not null
  ) then
    return;
  end if;
  perform net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret),
    body := '{}'::jsonb,
    timeout_milliseconds := 10000
  );
end;
$$;


ALTER FUNCTION "private"."invoke_payments_reconciliation"() OWNER TO "postgres";

