-- Name: lock_stock("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."lock_stock"("p_product_id" "uuid") RETURNS "public"."product_stock"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_row public.product_stock;
begin
  if not exists (select 1 from public.products where id = p_product_id) then
    perform private.inventory_error('unknown_product');
  end if;
  insert into public.product_stock (product_id) values (p_product_id)
  on conflict (product_id) do nothing;
  select * into v_row from public.product_stock
  where product_id = p_product_id for update;
  return v_row;
end;
$$;


