--
-- Name: log_config_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."log_config_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
begin
  if tg_op = 'UPDATE' and (v_old - 'updated_at') = (v_new - 'updated_at') then
    return null;
  end if;
  insert into public.config_changes (table_name, row_id, operation, old_row, new_row, changed_by)
  values (
    tg_table_name,
    coalesce(v_new ->> 'id', v_old ->> 'id', v_new ->> 'key', v_old ->> 'key'),
    tg_op, v_old, v_new, auth.uid()
  );
  return null;
end;
$$;


ALTER FUNCTION "private"."log_config_change"() OWNER TO "postgres";

--
-- Name: log_order_status(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."log_order_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
    values (
      new.id,
      case when tg_op = 'UPDATE' then old.status end,
      new.status,
      coalesce(auth.uid(), nullif(current_setting('app.order_event_actor', true), '')::uuid),
      coalesce(
        case new.status
          when 'cancelled' then new.cancel_reason
          when 'refunded' then coalesce(
            new.void_reason,
            case when new.refund_reference is not null
                 then 'Reembolso registrado (' || new.refund_reference || '): ' || new.refund_note end,
            new.refund_reason)
        end,
        nullif(current_setting('app.order_event_reason', true), '')
      )
    );
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."log_order_status"() OWNER TO "postgres";

