--
-- Name: nit_check_digit("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."nit_check_digit"("p_nit" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select case when r < 2 then r else 11 - r end
  from (
    select sum(substr(reverse(p_nit), i, 1)::integer
               * (array[3, 7, 13, 17, 19, 23, 29, 37, 41, 43, 47, 53, 59, 67, 71])[i]) % 11 as r
    from generate_series(1, length(p_nit)) as i
  ) s
  where p_nit ~ '^[0-9]{1,15}$';
$_$;


ALTER FUNCTION "private"."nit_check_digit"("p_nit" "text") OWNER TO "postgres";

--
-- Name: nit_matches("text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."nit_matches"("p_typed" "text", "p_registered" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    p_typed = p_registered
    or (length(p_typed) = length(p_registered) + 1
        and left(p_typed, -1) = p_registered
        and right(p_typed, 1)::integer = private.nit_check_digit(p_registered))
    or (length(p_registered) = length(p_typed) + 1
        and left(p_registered, -1) = p_typed
        and right(p_registered, 1)::integer = private.nit_check_digit(p_typed)),
    false
  );
$$;


ALTER FUNCTION "private"."nit_matches"("p_typed" "text", "p_registered" "text") OWNER TO "postgres";

--
-- Name: normalize_id_document("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."normalize_id_document"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when v ~ '^[0-9]{5,12}$' then v
  end
  from (select regexp_replace(coalesce(p_value, ''), '[.\s-]', '', 'g') as v) s;
$_$;


ALTER FUNCTION "private"."normalize_id_document"("p_value" "text") OWNER TO "postgres";

