-- Name: pos_quote("jsonb", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."pos_quote"("p_items" "jsonb", "p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_own text := current_setting('request.jwt.claims', true);
  v_claims jsonb := private.pos_buyer_claims(p_customer_id);
  v_quote jsonb;
begin
  if v_claims is null then
    return null;
  end if;
  perform set_config('request.jwt.claims', v_claims::text, true);
  v_quote := public.quote_items(p_items);
  perform set_config('request.jwt.claims', v_own, true);
  return v_quote;
end;
$$;


