--
-- Name: release_reservations("text", "public"."reservation_status", boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."release_reservations"("p_reference" "text", "p_status" "public"."reservation_status", "p_only_expired" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_res public.stock_reservations;
  v_count integer := 0;
begin
  for v_res in
    select * from public.stock_reservations
    where status = 'active'
      and (p_reference is null or reference = p_reference)
      and (not p_only_expired or expires_at <= now())
    order by product_id
    for update skip locked
  loop
    perform private.lock_stock(v_res.product_id);
    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reservation_id)
    values
      (v_res.product_id, 'reservation_release', -v_res.units, v_res.reference, v_res.id);
    update public.stock_reservations set status = p_status where id = v_res.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "private"."release_reservations"("p_reference" "text", "p_status" "public"."reservation_status", "p_only_expired" boolean) OWNER TO "postgres";

--
-- Name: request_credit_note_kind("uuid", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."request_credit_note_kind"("p_invoice_id" "uuid", "p_reason" "text", "p_kind" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_invoice public.invoices;
  v_id uuid;
  v_existing_kind text;
begin
  if not (private.is_service_role() or private.has_staff_role(array['admin'])) then
    raise exception 'credit_note_forbidden' using errcode = '42501';
  end if;
  if p_kind not in ('full', 'products_only') then
    raise exception 'credit_note_invalid_kind' using errcode = '22023';
  end if;
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.status <> 'accepted' then
    raise exception 'credit_note_invoice_not_accepted' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'credit_note_missing_reason' using errcode = '22023';
  end if;

  insert into public.credit_notes (invoice_id, reference_code, reason, requested_by, kind, concept_code)
  values (p_invoice_id, 'NC-' || upper(replace(p_invoice_id::text, '-', '')), trim(p_reason), auth.uid(),
          p_kind, case when p_kind = 'full' then '2' else '1' end)
  on conflict (invoice_id) do nothing
  returning id into v_id;

  if v_id is null then
    -- Idempotent for the same kind; a note of the other kind is an error,
    -- never returned as if it were the one asked for.
    select id, kind into v_id, v_existing_kind from public.credit_notes where invoice_id = p_invoice_id;
    if v_existing_kind <> p_kind then
      raise exception 'credit_note_kind_conflict' using errcode = '22023';
    end if;
    return v_id;
  end if;

  perform public.enqueue_action(
    private.uuid_from_text('issue_credit_note:' || v_id::text),
    'issue_credit_note', null, jsonb_build_object('credit_note_id', v_id), 8
  );
  return v_id;
end;
$$;


ALTER FUNCTION "private"."request_credit_note_kind"("p_invoice_id" "uuid", "p_reason" "text", "p_kind" "text") OWNER TO "postgres";

--
-- Name: requeue_action("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."requeue_action"("p_action_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action public.actions;
  v_reason text := trim(coalesce(p_reason, ''));
  v_msg_id bigint;
begin
  if length(v_reason) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;
  select * into v_action from public.actions where id = p_action_id for update;
  if v_action.id is null then
    return jsonb_build_object('ok', false, 'error', 'action_not_found');
  end if;
  if v_action.status <> 'failed' then
    return jsonb_build_object('ok', false, 'error', 'action_not_failed', 'status', v_action.status);
  end if;

  select pgmq.send('actions', jsonb_build_object('action_id', v_action.id)) into v_msg_id;
  update public.actions
  set status = 'queued', attempts = 0, error = null, result = null,
      next_attempt_at = null, started_at = null, finished_at = null, queue_msg_id = v_msg_id
  where id = v_action.id;

  insert into public.action_retries (action_id, action_type, previous_error, reason, retried_by)
  values (v_action.id, v_action.type, v_action.error, v_reason, auth.uid());
  return jsonb_build_object('ok', true, 'action_id', v_action.id);
end;
$$;


ALTER FUNCTION "private"."requeue_action"("p_action_id" "uuid", "p_reason" "text") OWNER TO "postgres";

