--
-- Name: reserve_units("text", "jsonb", integer, "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."reserve_units"("p_reference" "text", "p_items" "jsonb", "p_ttl_minutes" integer, "p_created_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_units integer;
  v_stock public.product_stock;
  v_safety integer;
  v_reservation_id uuid;
begin
  if length(trim(coalesce(p_reference, ''))) = 0 then perform private.inventory_error('missing_reference'); end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    perform private.inventory_error('invalid_items');
  end if;

  for v_item in
    select value from jsonb_array_elements(p_items) order by value ->> 'product_id'
  loop
    v_product_id := (v_item ->> 'product_id')::uuid;
    v_units := (v_item ->> 'units')::integer;
    if v_units is null or v_units <= 0 then perform private.inventory_error('invalid_units'); end if;

    v_stock := private.lock_stock(v_product_id);
    select web_safety_stock into v_safety from public.products where id = v_product_id;
    if v_stock.on_hand - v_stock.reserved - v_safety < v_units then
      raise exception 'inventory_insufficient_stock'
        using errcode = '22023', detail = v_product_id::text;
    end if;

    insert into public.stock_reservations (product_id, units, reference, expires_at, created_by)
    values (v_product_id, v_units, trim(p_reference), now() + make_interval(mins => p_ttl_minutes), p_created_by)
    returning id into v_reservation_id;

    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reservation_id, created_by)
    values
      (v_product_id, 'reservation', v_units, trim(p_reference), v_reservation_id, p_created_by);
  end loop;
end;
$$;


ALTER FUNCTION "private"."reserve_units"("p_reference" "text", "p_items" "jsonb", "p_ttl_minutes" integer, "p_created_by" "uuid") OWNER TO "postgres";

--
-- Name: return_order_stock("uuid", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."return_order_stock"("p_order_id" "uuid", "p_reason" "text", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.order_items;
begin
  for v_item in select * from public.order_items where order_id = p_order_id order by product_id
  loop
    -- Same lock as every other stock change (D-038), in product order.
    perform private.lock_stock(v_item.product_id);
    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reason, created_by, idempotency_key)
    values
      (v_item.product_id, 'return_in', v_item.base_units, p_order_id::text, p_reason, p_actor,
       private.uuid_from_text('delivery_return:' || p_order_id || ':' || v_item.product_id))
    on conflict (idempotency_key) do nothing;
  end loop;
end;
$$;


ALTER FUNCTION "private"."return_order_stock"("p_order_id" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";

--
-- Name: sales_block_at("text", "uuid", timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sales_block_at"("p_channel" "text", "p_zone_id" "uuid", "p_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('block_id', b.id, 'name', b.name, 'message', b.message, 'ends_at', u.until)
  from public.sales_blocks b
  cross join lateral (select private.sales_block_until(b, p_at) as until) u
  where b.is_active
    and p_channel = any (b.channels)
    and (b.zone_id is null or b.zone_id = p_zone_id)
    and u.until is not null
  order by u.until desc
  limit 1;
$$;


ALTER FUNCTION "private"."sales_block_at"("p_channel" "text", "p_zone_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";

--
-- Name: sales_blocks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."sales_blocks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "kind" "public"."sales_block_kind" NOT NULL,
    "zone_id" "uuid",
    "channels" "text"[] DEFAULT ARRAY['web'::"text", 'pos'::"text"] NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "weekdays" smallint[],
    "start_time" time without time zone,
    "end_time" time without time zone,
    "message" "text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sales_blocks_channels_check" CHECK (((("cardinality"("channels") >= 1) AND ("cardinality"("channels") <= 2)) AND ("channels" <@ ARRAY['web'::"text", 'pos'::"text"]))),
    CONSTRAINT "sales_blocks_date_range_check" CHECK ((("kind" <> 'date_range'::"public"."sales_block_kind") OR (("starts_at" IS NOT NULL) AND ("ends_at" IS NOT NULL) AND ("weekdays" IS NULL) AND ("start_time" IS NULL) AND ("end_time" IS NULL)))),
    CONSTRAINT "sales_blocks_message_check" CHECK ((("length"(TRIM(BOTH FROM "message")) >= 3) AND ("length"(TRIM(BOTH FROM "message")) <= 300))),
    CONSTRAINT "sales_blocks_name_check" CHECK ((("length"(TRIM(BOTH FROM "name")) >= 1) AND ("length"(TRIM(BOTH FROM "name")) <= 80))),
    CONSTRAINT "sales_blocks_range_check" CHECK ((("starts_at" IS NULL) OR ("ends_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "sales_blocks_weekly_check" CHECK ((("kind" <> 'weekly'::"public"."sales_block_kind") OR (("weekdays" IS NOT NULL) AND (("cardinality"("weekdays") >= 1) AND ("cardinality"("weekdays") <= 7)) AND ("weekdays" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]) AND ("start_time" IS NOT NULL) AND ("end_time" IS NOT NULL) AND ("start_time" <> "end_time"))))
);


ALTER TABLE "public"."sales_blocks" OWNER TO "postgres";

--
-- Name: sales_block_until("public"."sales_blocks", timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sales_block_until"("p_block" "public"."sales_blocks", "p_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_local timestamp := p_at at time zone 'America/Bogota';
  v_day integer := extract(isodow from v_local)::integer;
  v_prev integer := case when extract(isodow from v_local)::integer = 1 then 7
                         else extract(isodow from v_local)::integer - 1 end;
  v_time time := v_local::time;
  v_end_local timestamp;
  v_until timestamptz;
begin
  if p_block.starts_at is not null and p_at < p_block.starts_at then return null; end if;
  if p_block.ends_at is not null and p_at >= p_block.ends_at then return null; end if;

  if p_block.kind = 'date_range' then
    return p_block.ends_at;
  end if;

  if p_block.start_time < p_block.end_time then
    if v_day = any (p_block.weekdays) and v_time >= p_block.start_time and v_time < p_block.end_time then
      v_end_local := v_local::date + p_block.end_time;
    end if;
  else
    -- Crosses midnight: started today, or started yesterday and still on.
    if v_day = any (p_block.weekdays) and v_time >= p_block.start_time then
      v_end_local := (v_local::date + 1) + p_block.end_time;
    elsif v_prev = any (p_block.weekdays) and v_time < p_block.end_time then
      v_end_local := v_local::date + p_block.end_time;
    end if;
  end if;

  if v_end_local is null then return null; end if;
  v_until := v_end_local at time zone 'America/Bogota';
  return case when p_block.ends_at is not null and p_block.ends_at < v_until then p_block.ends_at else v_until end;
end;
$$;


ALTER FUNCTION "private"."sales_block_until"("p_block" "public"."sales_blocks", "p_at" timestamp with time zone) OWNER TO "postgres";

