--
-- Name: admin_list_pos_sales(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_list_pos_sales"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  return coalesce((
    select jsonb_agg(row_data order by created_at desc, order_id)
    from (
      select o.created_at, o.id as order_id, jsonb_build_object(
        'order_id', o.id,
        'created_at', o.created_at,
        'status', o.status,
        'total_cop', o.total_cop,
        'payment_method', o.pos_payment_method,
        'cashier', private.staff_display_name(o.cashier_id),
        -- Company name for wholesale buyers, as on their invoice.
        'customer', coalesce(c.business_name, c.full_name),
        -- Bottles (base units), whether sold by unit or by box.
        'units', o.total_base_units,
        'invoice_status', inv.status,
        'invoice_number', inv.factus_number,
        'voided_at', o.voided_at,
        'void_reason', o.void_reason,
        'voided_by', private.staff_display_name(o.voided_by)
      ) as row_data
      from public.orders o
      left join public.customers c on c.id = o.customer_id
      left join public.invoices inv on inv.order_id = o.id
      where o.channel = 'pos'
      order by o.created_at desc, o.id
      limit least(greatest(coalesce(p_limit, 50), 1), 200)
    ) s
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."admin_list_pos_sales"("p_limit" integer) OWNER TO "postgres";

--
-- Name: admin_list_refunds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_list_refunds"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  return coalesce((
    select jsonb_agg(row_data order by sort_ts) from (
    select o.updated_at as sort_ts, jsonb_build_object(
      'kind', 'order', 'attempt_id', null,
      'order_id', o.id, 'status', o.status, 'total_cop', o.total_cop, 'refund_reason', o.refund_reason,
      'refund_amount_cop', coalesce(o.refund_amount_cop, o.total_cop),
      'products_only', o.refund_amount_cop is not null,
      'paid_at', o.paid_at, 'customer', coalesce(c.full_name, 'Cliente'), 'email', u.email,
      'transaction_id', (select a.wompi_transaction_id from public.payment_attempts a
                         where a.order_id = o.id and a.status = 'approved' and not a.refund_needed
                         order by a.finalized_at desc limit 1)
    ) as row_data
    from public.orders o
    left join public.customers c on c.id = o.customer_id
    left join auth.users u on u.id = o.customer_id
    where private.order_refund_pending(o)
    union all
    -- A duplicate payment: only that attempt's money goes back (D-072).
    select pa.updated_at, jsonb_build_object(
      'kind', 'payment', 'attempt_id', pa.id,
      'order_id', o.id, 'status', o.status, 'total_cop', pa.amount_in_cents / 100, 'refund_reason', pa.refund_reason,
      'refund_amount_cop', pa.amount_in_cents / 100, 'products_only', false,
      'paid_at', pa.finalized_at, 'customer', coalesce(c.full_name, 'Cliente'), 'email', u.email,
      'transaction_id', pa.wompi_transaction_id
    )
    from public.payment_attempts pa
    join public.orders o on o.id = pa.order_id
    left join public.customers c on c.id = o.customer_id
    left join auth.users u on u.id = o.customer_id
    where private.attempt_refund_pending(pa)
    ) s
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."admin_list_refunds"() OWNER TO "postgres";

--
-- Name: admin_list_staff(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_list_staff"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  return jsonb_build_object(
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', u.id,
        'email', u.email,
        'full_name', coalesce(u.raw_user_meta_data ->> 'full_name', u.email),
        'staff_role', u.raw_app_meta_data ->> 'staff_role',
        'last_sign_in_at', u.last_sign_in_at
      ) order by u.raw_app_meta_data ->> 'staff_role', u.email)
      from auth.users u
      where u.raw_app_meta_data ? 'staff_role' and u.email_confirmed_at is not null
    ), '[]'::jsonb),
    'invitations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'email', i.email, 'full_name', i.full_name, 'staff_role', i.staff_role,
        'expires_at', i.expires_at, 'expired', i.expires_at <= now()
      ) order by i.created_at desc)
      from public.staff_invitations i
      where i.status = 'pending'
    ), '[]'::jsonb)
  );
end;
$$;


