--
-- Name: admin_queue_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_queue_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  return jsonb_build_object(
    'failed', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'type', a.type, 'error', a.error, 'attempts', a.attempts,
        'max_attempts', a.max_attempts, 'payload', a.payload, 'finished_at', a.finished_at
      ) order by a.finished_at desc)
      from (select * from public.actions where status = 'failed' order by finished_at desc limit 100) a
    ), '[]'::jsonb),
    'overdue', (select count(*) from public.actions a where private.action_overdue(a)),
    'stalled', (select count(*) from public.actions a where private.action_stalled(a)),
    'queued', (select count(*) from public.actions where status = 'queued'),
    'failed_count', (select count(*) from public.actions where status = 'failed')
  );
end;
$$;


ALTER FUNCTION "public"."admin_queue_status"() OWNER TO "postgres";

--
-- Name: admin_reset_pickup_attempts("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_reset_pickup_attempts"("p_order_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := trim(coalesce(p_reason, ''));
  v_order public.orders;
begin
  perform private.require_admin();
  if length(v_reason) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null or v_order.channel <> 'web' or v_order.fulfillment <> 'pickup' then
    return jsonb_build_object('ok', false, 'error', 'order_not_found');
  end if;
  update private.order_pickup_documents set failed_attempts = 0, updated_at = now()
  where order_id = p_order_id and failed_attempts > 0;
  if not found then
    return jsonb_build_object('ok', true, 'changed', false);
  end if;
  insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
  values (p_order_id, v_order.status, v_order.status, auth.uid(),
          'Intentos de recogida reiniciados: ' || v_reason);
  return jsonb_build_object('ok', true, 'changed', true);
end;
$$;


ALTER FUNCTION "public"."admin_reset_pickup_attempts"("p_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: admin_sales_blocks_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_sales_blocks_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  return jsonb_build_object(
    'rules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id, 'name', b.name, 'kind', b.kind, 'zone_id', b.zone_id, 'municipality', z.municipality,
        'channels', to_jsonb(b.channels), 'starts_at', b.starts_at, 'ends_at', b.ends_at,
        'weekdays', to_jsonb(b.weekdays), 'start_time', b.start_time, 'end_time', b.end_time,
        'message', b.message, 'is_active', b.is_active,
        -- sales_block_until ignores is_active: an inactive rule never blocks.
        'blocking_until', case when b.is_active then private.sales_block_until(b, now()) end,
        'created_by', private.staff_display_name(b.created_by),
        'created_at', b.created_at,
        'updated_by', private.staff_display_name(b.updated_by),
        'updated_at', b.updated_at
      ) order by b.is_active desc, b.updated_at desc, b.id)
      from public.sales_blocks b
      left join public.delivery_zones z on z.id = b.zone_id
    ), '[]'::jsonb),
    -- Every municipality and channel blocked now, with the rule and until when.
    -- The POS only sells at the store, so it is evaluated only for the store's
    -- municipality (a department-wide rule is one POS line, not ten).
    'blocked_now', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zone_id', z.id, 'municipality', z.municipality, 'channel', c.channel,
        'block_id', s.block ->> 'block_id', 'name', s.block ->> 'name', 'ends_at', s.block ->> 'ends_at'
      ) order by z.municipality, c.channel)
      from public.delivery_zones z
      cross join (values ('web'), ('pos')) c(channel)
      cross join lateral (select private.sales_block_at(c.channel, z.id, now()) as block) s
      where s.block is not null
        and (c.channel = 'web' or z.id = private.store_zone_id())
    ), '[]'::jsonb),
    'store_zone_id', private.store_zone_id(),
    'changes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'block_id', ch.block_id, 'operation', ch.operation,
        'name', coalesce(ch.new_row ->> 'name', ch.old_row ->> 'name'),
        'old_row', ch.old_row, 'new_row', ch.new_row,
        'actor', private.staff_display_name(ch.actor_id), 'created_at', ch.created_at
      ) order by ch.created_at desc, ch.id)
      from (select * from public.sales_block_changes order by created_at desc, id limit 30) ch
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_sales_blocks_overview"() OWNER TO "postgres";

--
-- Name: admin_summary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_inventory jsonb;
begin
  perform private.require_admin();
  -- After the role check (D-056): nothing costly before it.
  v_inventory := private.inventory_alert_counts();
  return jsonb_build_object(
    'pending_wholesale', (select count(*) from public.customers where wholesale_status = 'pending'),
    'staff', (select count(*) from auth.users where raw_app_meta_data ? 'staff_role' and email_confirmed_at is not null),
    'pending_invitations', (select count(*) from public.staff_invitations where status = 'pending' and expires_at > now()),
    'invoices_attention',
      (select count(*) from private.invoices_in_play where needs_attention)
      + (select count(*) from private.credit_notes_in_play where needs_attention),
    'failed_actions', (select count(*) from public.actions where status = 'failed'),
    'queue_stuck', (select count(*) from public.actions a
                    where private.action_overdue(a) or private.action_stalled(a)),
    'refunds_pending',
      (select count(*) from public.orders o where private.order_refund_pending(o))
      + (select count(*) from public.payment_attempts pa where private.attempt_refund_pending(pa)),
    'low_stock', (v_inventory ->> 'low_stock')::integer,
    'stock_mismatches', (v_inventory ->> 'stock_mismatches')::integer,
    'deliveries_to_assign', (
      select count(*) from public.orders o
      where o.channel = 'web' and o.fulfillment = 'delivery' and not o.needs_refund and o.status in ('paid', 'preparing')
        and not private.delivery_awaiting_choice(o)
    ),
    'deliveries_failed', (
      select count(*) from public.orders o
      where o.channel = 'web' and o.fulfillment = 'delivery' and not o.needs_refund and o.status = 'preparing'
        and private.delivery_awaiting_choice(o)
    ),
    'pickups_attention', (select count(*) from private.pickups_needing_attention)
  );
end;
$$;


ALTER FUNCTION "public"."admin_summary"() OWNER TO "postgres";

--
-- Name: apply_expired_return_choices(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."apply_expired_return_choices"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count integer;
begin
  with expired as (
    update public.orders
    set return_choice = 'pickup', return_choice_at = now(), return_choice_defaulted = true,
        fulfillment = 'pickup'
    where delivery_return_kind = 'customer' and return_choice is null
      and return_choice_deadline <= now() and status = 'preparing'
    returning id, status
  ), logged as (
    insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
    select id, status, status, null, 'Sin elección del cliente en 3 días: queda para recoger en la tienda'
    from expired
    returning 1
  )
  select count(*) into v_count from logged;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."apply_expired_return_choices"() OWNER TO "postgres";

--
-- Name: apply_payment_event("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."apply_payment_event"("p_event_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.payment_events;
  v_attempt public.payment_attempts;
  v_order public.orders;
  v_outcome text;
  v_items jsonb;
begin
  select * into v_event from public.payment_events where id = p_event_id for update;
  if v_event.id is null then
    raise exception 'payment_event_not_found' using errcode = '22023';
  end if;
  if v_event.processed_at is not null then
    return 'already_processed';
  end if;

  if v_event.event_type <> 'transaction.updated' or v_event.reference is null then
    v_outcome := 'not_a_transaction';
  else
    select * into v_attempt from public.payment_attempts
    where reference = v_event.reference for update;

    if v_attempt.id is null then
      v_outcome := 'unknown_reference';
    elsif v_event.amount_in_cents is distinct from v_attempt.amount_in_cents
       or v_event.currency is distinct from v_attempt.currency then
      -- Never accept a payment for a different amount: alert the admin.
      v_outcome := 'amount_mismatch';
    elsif v_attempt.status not in ('pending', 'abandoned') then
      v_outcome := 'already_final';
    elsif v_event.status = 'PENDING' then
      update public.payment_attempts
      set wompi_transaction_id = coalesce(wompi_transaction_id, v_event.transaction_id)
      where id = v_attempt.id;
      v_outcome := 'pending_ignored';
    elsif v_event.status in ('DECLINED', 'VOIDED', 'ERROR') then
      update public.payment_attempts
      set status = lower(v_event.status)::public.payment_attempt_status,
          wompi_transaction_id = coalesce(wompi_transaction_id, v_event.transaction_id),
          payment_method_type = v_event.payload #>> '{data,transaction,payment_method_type}',
          status_message = v_event.payload #>> '{data,transaction,status_message}',
          finalized_at = now()
      where id = v_attempt.id;
      v_outcome := 'applied_declined';
    elsif v_event.status = 'APPROVED' then
      update public.payment_attempts
      set status = 'approved',
          wompi_transaction_id = coalesce(wompi_transaction_id, v_event.transaction_id),
          payment_method_type = v_event.payload #>> '{data,transaction,payment_method_type}',
          status_message = v_event.payload #>> '{data,transaction,status_message}',
          finalized_at = now()
      where id = v_attempt.id;

      select * into v_order from public.orders where id = v_attempt.order_id for update;

      if v_order.status = 'awaiting_payment' then
        select jsonb_agg(jsonb_build_object('product_id', product_id, 'units', base_units))
        into v_items
        from public.order_items where order_id = v_order.id;

        begin
          -- Reservation -> web sale. Idempotent with the attempt id as key.
          perform public.consume_reservation(v_order.id::text, v_items, v_attempt.id);
          update public.orders
          set status = 'paid', paid_at = now()
          where id = v_order.id;
          -- The order is paid: an open attempt without a transaction is no
          -- longer usable (a later payment on it is still caught as a
          -- duplicate, D-072).
          update public.payment_attempts
          set status = 'abandoned'
          where order_id = v_order.id and id <> v_attempt.id
            and status = 'pending' and wompi_transaction_id is null;
        exception when sqlstate '22023' then
          -- Paid, but the stock is gone (reservation expired and sold): the
          -- order is paid and must be refunded by the admin (plan step 17).
          update public.orders
          set status = 'paid', paid_at = now(),
              needs_refund = true, refund_reason = 'insufficient_stock_after_payment'
          where id = v_order.id;
        end;
      elsif v_order.status = 'cancelled' and not v_order.needs_refund then
        -- Money arrived for an order that is no longer payable (e.g. cancelled
        -- after 24 hours): flag it for refund, do not reopen it (D-040).
        update public.orders
        set needs_refund = true, refund_reason = 'payment_for_closed_order'
        where id = v_order.id;
      else
        -- The order was already paid by another attempt (two tabs, a late
        -- checkout), or its refund is already counted: refund THIS payment
        -- only and leave the order alone, so it is still delivered and
        -- invoiced (D-072).
        update public.payment_attempts
        set refund_needed = true, refund_reason = 'duplicate_payment'
        where id = v_attempt.id;
      end if;
      v_outcome := 'applied_approved';
    else
      v_outcome := 'unknown_status';
    end if;
  end if;

  update public.payment_events
  set processed_at = now(), outcome = v_outcome
  where id = p_event_id;
  return v_outcome;
end;
$$;


ALTER FUNCTION "public"."apply_payment_event"("p_event_id" "uuid") OWNER TO "postgres";

--
-- Name: assign_delivery("uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."assign_delivery"("p_order_id" "uuid", "p_provider_id" "uuid", "p_courier_id" "uuid" DEFAULT NULL::"uuid", "p_external_ref" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.orders;
  v_provider public.delivery_providers;
begin
  if not (private.is_service_role() or private.has_staff_role(array['admin'])) then
    raise exception 'delivery_forbidden' using errcode = '42501';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null or v_order.fulfillment <> 'delivery' or v_order.needs_refund
     or v_order.status not in ('paid', 'preparing', 'out_for_delivery') then
    raise exception 'delivery_order_not_assignable' using errcode = '22023';
  end if;

  select * into v_provider from public.delivery_providers where id = p_provider_id and is_active;
  if v_provider.id is null then
    raise exception 'delivery_unknown_provider' using errcode = '22023';
  end if;

  if v_provider.kind = 'own' then
    if p_courier_id is null
       or not exists (
         select 1 from public.couriers
         where id = p_courier_id and provider_id = p_provider_id and is_active
       )
       or private.user_staff_role(p_courier_id) is distinct from 'courier' then
      raise exception 'delivery_invalid_courier' using errcode = '22023';
    end if;
  elsif p_courier_id is not null then
    -- Third parties are tracked by the administrator (D-026).
    raise exception 'delivery_invalid_courier' using errcode = '22023';
  end if;

  update public.orders
  set delivery_provider_id = p_provider_id,
      courier_id = p_courier_id,
      delivery_external_ref = nullif(trim(coalesce(p_external_ref, '')), ''),
      assigned_at = now(),
      status = 'out_for_delivery'
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "public"."assign_delivery"("p_order_id" "uuid", "p_provider_id" "uuid", "p_courier_id" "uuid", "p_external_ref" "text") OWNER TO "postgres";

