--
-- Name: cancel_abandoned_orders(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_abandoned_orders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order_id uuid;
  v_count integer := 0;
begin
  for v_order_id in
    select id from public.orders
    where status = 'awaiting_payment' and cancel_after <= now()
    for update skip locked
  loop
    if private.cancel_web_order(v_order_id, 'payment_window_expired') then
      v_count := v_count + 1;
    end if;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."cancel_abandoned_orders"() OWNER TO "postgres";

--
-- Name: cancel_order("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_order"("p_order_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  -- RLS: only the customer's own orders are visible.
  if not exists (
    select 1 from public.orders
    where id = p_order_id and customer_id = auth.uid() and status = 'awaiting_payment'
  ) then
    raise exception 'order_not_cancellable' using errcode = '22023';
  end if;
  return private.cancel_web_order(p_order_id, 'cancelled_by_customer');
end;
$$;


ALTER FUNCTION "public"."cancel_order"("p_order_id" "uuid") OWNER TO "postgres";

--
-- Name: choose_delivery_return_option("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."choose_delivery_return_option"("p_order_id" "uuid", "p_option" "text", "p_pickup_document" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders;
  v_digits text;
begin
  if v_uid is null then
    raise exception 'choice_requires_customer' using errcode = '42501';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found or v_order.customer_id is distinct from v_uid then
    return jsonb_build_object('ok', false, 'error', 'order_not_found');
  end if;
  if v_order.delivery_return_kind is distinct from 'customer' then
    return jsonb_build_object('ok', false, 'error', 'not_awaiting_choice');
  end if;
  -- Idempotent: the same choice twice answers the same.
  if v_order.return_choice is not null then
    if v_order.return_choice = p_option then
      return jsonb_build_object('ok', true, 'already_chosen', true);
    end if;
    return jsonb_build_object('ok', false, 'error', 'choice_already_made');
  end if;
  if v_order.status <> 'preparing' then
    return jsonb_build_object('ok', false, 'error', 'not_awaiting_choice');
  end if;
  if v_order.return_choice_deadline <= now() then
    return jsonb_build_object('ok', false, 'error', 'choice_expired');
  end if;
  if p_option is null or p_option not in ('pickup', 'reschedule', 'refund') then
    return jsonb_build_object('ok', false, 'error', 'invalid_option');
  end if;

  if p_option = 'pickup' then
    -- Without a NIT, the cédula of who picks it up (D-067).
    if not exists (select 1 from public.customers where id = v_uid and document_type = 'nit') then
      if nullif(btrim(coalesce(p_pickup_document, '')), '') is null then
        return jsonb_build_object('ok', false, 'error', 'pickup_document_required');
      end if;
      v_digits := private.normalize_id_document(p_pickup_document);
      if v_digits is null then
        return jsonb_build_object('ok', false, 'error', 'invalid_pickup_document');
      end if;
      insert into private.order_pickup_documents (order_id, document_hash, document_last3)
      values (v_order.id, private.pickup_document_hash(v_order.id, v_digits), right(v_digits, 3))
      on conflict (order_id) do update
        set document_hash = excluded.document_hash, document_last3 = excluded.document_last3,
            failed_attempts = 0, updated_at = now();
    end if;
    update public.orders set fulfillment = 'pickup' where id = v_order.id;
  elsif p_option = 'reschedule' then
    -- Next day, without charging the delivery again (D-059).
    update public.orders set scheduled_delivery_on = private.bogota_tomorrow() where id = v_order.id;
  else
    -- Products only: the delivery was attempted (D-059).
    update public.orders
    set needs_refund = true, refund_reason = 'customer_chose_refund', refund_amount_cop = subtotal_cop
    where id = v_order.id;
    -- The bottles are back at the store and can be sold again (D-069).
    perform private.return_order_stock(v_order.id, 'Domicilio fallido: el cliente pidió el reembolso', v_uid);
  end if;

  update public.orders set return_choice = p_option, return_choice_at = now() where id = v_order.id;
  insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
  values (v_order.id, v_order.status, v_order.status, v_uid,
          'El cliente eligió: ' || case p_option
            when 'pickup' then 'recoger en la tienda'
            when 'reschedule' then 'un nuevo envío mañana'
            else 'el reembolso de los productos' end);
  return jsonb_build_object('ok', true, 'already_chosen', false);
end;
$$;


ALTER FUNCTION "public"."choose_delivery_return_option"("p_order_id" "uuid", "p_option" "text", "p_pickup_document" "text") OWNER TO "postgres";

--
-- Name: claim_actions(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."claim_actions"("p_batch" integer DEFAULT 10, "p_visibility_seconds" integer DEFAULT 60) RETURNS TABLE("action_id" "uuid", "type" "text", "user_id" "uuid", "payload" "jsonb", "attempt" integer, "max_attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_msg record;
  v_action public.actions%rowtype;
  v_returned integer := 0;
  v_read integer;
begin
  -- Every message read is either handed out, archived or left hidden for
  -- p_visibility_seconds, so reading again never returns it: the loop ends
  -- when the batch is full or no message is visible.
  loop
    v_read := 0;
    for v_msg in
      select * from pgmq.read('actions', p_visibility_seconds, p_batch - v_returned)
    loop
      v_read := v_read + 1;

      select * into v_action
      from public.actions a
      where a.id = (v_msg.message ->> 'action_id')::uuid
      for update;

      -- Orphan message or action already finished: drop the message.
      if v_action.id is null or v_action.status in ('succeeded', 'failed') then
        perform pgmq.archive('actions', v_msg.msg_id);
        continue;
      end if;

      -- Another worker is still running it: do not run it twice. pgmq.read
      -- already hid its message for p_visibility_seconds; that worker
      -- completes or fails it.
      if v_action.status = 'processing'
         and coalesce(v_action.started_at, v_action.updated_at) > now() - interval '10 minutes' then
        continue;
      end if;

      -- The worker died on every previous attempt: give up.
      if v_action.attempts >= v_action.max_attempts then
        update public.actions
        set status = 'failed',
            error = coalesce(error, 'max_attempts_reached'),
            finished_at = now(),
            next_attempt_at = null
        where id = v_action.id;
        perform pgmq.archive('actions', v_msg.msg_id);
        continue;
      end if;

      update public.actions
      set status = 'processing',
          attempts = attempts + 1,
          started_at = now(),
          next_attempt_at = null,
          queue_msg_id = v_msg.msg_id
      where id = v_action.id;

      action_id := v_action.id;
      type := v_action.type;
      user_id := v_action.user_id;
      payload := v_action.payload;
      attempt := v_action.attempts + 1;
      max_attempts := v_action.max_attempts;
      v_returned := v_returned + 1;
      return next;
    end loop;

    exit when v_read = 0 or v_returned >= p_batch;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_actions"("p_batch" integer, "p_visibility_seconds" integer) OWNER TO "postgres";

