-- Name: clear_mismatched_payment_hint("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."clear_mismatched_payment_hint"("p_attempt_id" "uuid", "p_transaction_id" "text", "p_wompi_reference" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.payment_attempts
  set transaction_id_hint = null
  where id = p_attempt_id
    and transaction_id_hint = p_transaction_id
    and reference is distinct from p_wompi_reference;
  if not found then
    return false;
  end if;
  perform private.close_attempt_without_payment(p_attempt_id);
  return true;
end;
$$;


