-- Name: complete_action("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."complete_action"("p_action_id" "uuid", "p_result" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_msg_id bigint;
begin
  update public.actions
  set status = 'succeeded',
      result = p_result,
      error = null,
      finished_at = now(),
      next_attempt_at = null
  where id = p_action_id and status = 'processing'
  returning queue_msg_id into v_msg_id;

  if v_msg_id is not null then
    perform pgmq.archive('actions', v_msg_id);
  end if;
end;
$$;


