--
-- Name: confirm_pickup("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."confirm_pickup"("p_order_id" "uuid", "p_document" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders;
  v_doc private.order_pickup_documents;
  v_digits text;
  v_nit text;
  v_kind text;
  v_match boolean;
  v_failed integer;
begin
  if v_uid is null then
    raise exception 'pickup_requires_customer' using errcode = '42501';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  -- Another customer's order looks the same as a missing one.
  if not found or v_order.customer_id is distinct from v_uid then
    return jsonb_build_object('ok', false, 'error', 'order_not_found');
  end if;

  -- Idempotent: a second click after the confirmation answers the same.
  if exists (select 1 from public.pickup_confirmations where order_id = p_order_id) then
    return jsonb_build_object('ok', true, 'already_confirmed', true);
  end if;

  if v_order.channel <> 'web' or v_order.fulfillment <> 'pickup' then
    return jsonb_build_object('ok', false, 'error', 'not_pickup_order');
  end if;
  if v_order.status not in ('paid', 'preparing') or v_order.needs_refund then
    return jsonb_build_object('ok', false, 'error', 'pickup_not_available');
  end if;

  select * into v_doc from private.order_pickup_documents where order_id = p_order_id;
  if private.pickup_locked(v_doc.failed_attempts) then
    return jsonb_build_object('ok', false, 'error', 'pickup_locked');
  end if;

  v_digits := private.normalize_id_document(p_document);
  if v_digits is null then
    -- A malformed value is not counted as an attempt.
    return jsonb_build_object('ok', false, 'error', 'invalid_document');
  end if;

  -- Each order is confirmed with the method it was placed with: the cédula
  -- given at order time if there is one, otherwise the registered NIT.
  if v_doc.document_hash is not null then
    v_kind := 'cedula';
    v_match := private.pickup_document_hash(v_order.id, v_digits) = v_doc.document_hash;
  else
    select replace(document_number, '-', '') into v_nit
    from public.customers
    where id = v_uid and document_type = 'nit';
    if v_nit is null then
      -- Orders placed before step 18a: the store resolves them.
      return jsonb_build_object('ok', false, 'error', 'pickup_document_missing');
    end if;
    v_kind := 'nit';
    v_match := private.nit_matches(v_digits, v_nit);
  end if;

  -- Fails closed: a comparison that could not be made is a mismatch.
  if v_match is not true then
    insert into private.order_pickup_documents (order_id, failed_attempts)
    values (v_order.id, 1)
    on conflict (order_id) do update
      set failed_attempts = private.order_pickup_documents.failed_attempts + 1,
          updated_at = now()
    returning failed_attempts into v_failed;
    return jsonb_build_object(
      'ok', false, 'error', 'document_mismatch',
      'attempts_left', greatest(private.pickup_max_attempts() - v_failed, 0)
    );
  end if;

  insert into public.pickup_confirmations (order_id, confirmed_by, document_kind)
  values (v_order.id, v_uid, v_kind);

  update public.orders
  set status = 'delivered', delivered_at = now()
  where id = v_order.id;

  return jsonb_build_object('ok', true, 'already_confirmed', false);
end;
$$;


ALTER FUNCTION "public"."confirm_pickup"("p_order_id" "uuid", "p_document" "text") OWNER TO "postgres";

--
-- Name: consume_reservation("text", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."consume_reservation"("p_reference" "text", "p_items" "jsonb", "p_idempotency_key" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_units integer;
  v_res public.stock_reservations;
  v_stock public.product_stock;
  v_count integer := 0;
begin
  perform private.require_staff(array['admin']);
  -- Already consumed with this key: do nothing (webhook retries).
  if exists (
    select 1 from public.inventory_movements
    where reference = trim(p_reference) and movement_type = 'web_sale'
      and idempotency_key = p_idempotency_key
  ) then
    return 0;
  end if;

  for v_item in
    select value from jsonb_array_elements(p_items) order by value ->> 'product_id'
  loop
    v_product_id := (v_item ->> 'product_id')::uuid;
    v_units := (v_item ->> 'units')::integer;
    v_stock := private.lock_stock(v_product_id);

    select * into v_res from public.stock_reservations
    where reference = trim(p_reference) and product_id = v_product_id and status = 'active'
    for update;

    if v_res.id is not null then
      -- Release first, then sell: the units stop being reserved and leave.
      insert into public.inventory_movements
        (product_id, movement_type, units, reference, reservation_id)
      values (v_product_id, 'reservation_release', -v_res.units, v_res.reference, v_res.id);
      update public.stock_reservations set status = 'consumed' where id = v_res.id;
      v_stock := private.lock_stock(v_product_id);
    end if;

    if v_stock.on_hand - v_stock.reserved < v_units then
      raise exception 'inventory_insufficient_stock'
        using errcode = '22023', detail = v_product_id::text;
    end if;

    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reservation_id, idempotency_key)
    values (
      v_product_id, 'web_sale', -v_units, trim(p_reference), v_res.id,
      -- The key marks the first line only; the rest of the lines are covered
      -- because the whole function runs in one transaction.
      case when v_count = 0 then p_idempotency_key end
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."consume_reservation"("p_reference" "text", "p_items" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: create_pos_sale("uuid", "jsonb", "text", bigint, "uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."create_pos_sale"("p_idempotency_key" "uuid", "p_items" "jsonb", "p_payment_method" "text", "p_cash_received_cop" bigint, "p_customer_id" "uuid", "p_age_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.actions;
  v_detail text;
begin
  perform private.require_pos_staff();
  if p_idempotency_key is null then
    raise exception 'pos_missing_idempotency_key' using errcode = '22023';
  end if;

  -- A retry of a sale already registered returns it.
  select * into v_existing from public.actions
  where idempotency_key = p_idempotency_key and user_id = auth.uid() and type = 'pos_sale'
    and status = 'succeeded';
  if found then
    return jsonb_build_object('ok', true, 'created', false, 'tracking_id', v_existing.id,
                              'order_id', v_existing.result ->> 'order_id');
  end if;

  begin
    return private.create_pos_order(
      p_idempotency_key, p_items, p_payment_method, p_cash_received_cop, p_customer_id, p_age_confirmed
    );
  exception when sqlstate '22023' then
    get stacked diagnostics v_detail = pg_exception_detail;
    case sqlerrm
      when 'pos_age_not_confirmed' then return jsonb_build_object('ok', false, 'error', 'age_not_confirmed');
      when 'pos_invalid_payment_method' then return jsonb_build_object('ok', false, 'error', 'invalid_payment_method');
      when 'pos_customer_not_found' then return jsonb_build_object('ok', false, 'error', 'customer_not_found');
      when 'pos_quote_failed' then return jsonb_build_object('ok', false, 'error', 'quote_failed', 'quote', v_detail::jsonb);
      when 'pos_cash_insufficient' then return jsonb_build_object('ok', false, 'error', 'cash_insufficient') || v_detail::jsonb;
      when 'inventory_insufficient_stock' then return jsonb_build_object('ok', false, 'error', 'insufficient_stock') || v_detail::jsonb;
      when 'sales_blocked' then return jsonb_build_object('ok', false, 'error', 'sales_blocked', 'block', v_detail::jsonb);
      else raise;
    end case;
  end;
end;
$$;


ALTER FUNCTION "public"."create_pos_sale"("p_idempotency_key" "uuid", "p_items" "jsonb", "p_payment_method" "text", "p_cash_received_cop" bigint, "p_customer_id" "uuid", "p_age_confirmed" boolean) OWNER TO "postgres";

--
-- Name: deactivate_staff("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."deactivate_staff"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  v_reason text := trim(coalesce(p_reason, ''));
  v_open integer;
begin
  perform private.require_admin();
  if p_user_id = auth.uid() then
    return jsonb_build_object('ok', false, 'error', 'cannot_deactivate_self');
  end if;
  if length(v_reason) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;

  select raw_app_meta_data ->> 'staff_role' into v_role from auth.users where id = p_user_id for update;
  if v_role is null then
    return jsonb_build_object('ok', false, 'error', 'not_staff');
  end if;

  update auth.users
  set raw_app_meta_data = (raw_app_meta_data - 'staff_role') || '{"staff_deactivated": true}'::jsonb,
      -- Auth cannot read 'infinity' (sign-in answered 500): a far date.
      banned_until = now() + interval '100 years'
  where id = p_user_id;
  update public.couriers set is_active = false where id = p_user_id;
  insert into public.staff_changes (user_id, change, previous_role, reason, changed_by)
  values (p_user_id, 'deactivated', v_role, v_reason, auth.uid());

  select count(*) into v_open from public.orders where courier_id = p_user_id and status = 'out_for_delivery';
  return jsonb_build_object('ok', true, 'previous_role', v_role, 'open_deliveries', v_open);
end;
$$;


ALTER FUNCTION "public"."deactivate_staff"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";

