-- Name: delete_delivery_address("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."delete_delivery_address"("p_address_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
