--
-- Name: enqueue_action("uuid", "text", "uuid", "jsonb", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enqueue_action"("p_idempotency_key" "uuid", "p_type" "text", "p_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_max_attempts" integer DEFAULT 5) RETURNS TABLE("tracking_id" "uuid", "created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_existing public.actions%rowtype;
  v_msg_id bigint;
begin
  insert into public.actions (idempotency_key, type, user_id, payload, max_attempts)
  values (p_idempotency_key, p_type, p_user_id, coalesce(p_payload, '{}'::jsonb), p_max_attempts)
  on conflict (idempotency_key) do nothing
  returning id into v_id;

  if v_id is not null then
    select pgmq.send('actions', jsonb_build_object('action_id', v_id)) into v_msg_id;
    update public.actions set queue_msg_id = v_msg_id where id = v_id;
    return query select v_id, true;
    return;
  end if;

  select * into v_existing
  from public.actions
  where idempotency_key = p_idempotency_key;

  if v_existing.user_id is distinct from p_user_id or v_existing.type <> p_type then
    raise exception 'idempotency_key_conflict'
      using errcode = 'P0001',
            hint = 'The key is already used by another action. Generate a new key for a new intent.';
  end if;

  return query select v_existing.id, false;
end;
$$;


ALTER FUNCTION "public"."enqueue_action"("p_idempotency_key" "uuid", "p_type" "text", "p_user_id" "uuid", "p_payload" "jsonb", "p_max_attempts" integer) OWNER TO "postgres";

--
-- Name: fail_action("uuid", "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."fail_action"("p_action_id" "uuid", "p_error" "text", "p_permanent" boolean DEFAULT false) RETURNS "public"."action_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action public.actions%rowtype;
  v_delay integer;
begin
  select * into v_action
  from public.actions
  where id = p_action_id and status = 'processing'
  for update;

  if v_action.id is null then
    return null;
  end if;

  if p_permanent or v_action.attempts >= v_action.max_attempts then
    update public.actions
    set status = 'failed',
        error = left(p_error, 2000),
        finished_at = now(),
        next_attempt_at = null
    where id = p_action_id;
    if v_action.queue_msg_id is not null then
      perform pgmq.archive('actions', v_action.queue_msg_id);
    end if;
    return 'failed'::public.action_status;
  end if;

  v_delay := private.action_backoff_seconds(v_action.attempts);
  update public.actions
  set status = 'queued',
      error = left(p_error, 2000),
      next_attempt_at = now() + make_interval(secs => v_delay)
  where id = p_action_id;
  if v_action.queue_msg_id is not null then
    perform pgmq.set_vt('actions', v_action.queue_msg_id, v_delay);
  end if;
  return 'queued'::public.action_status;
end;
$$;


ALTER FUNCTION "public"."fail_action"("p_action_id" "uuid", "p_error" "text", "p_permanent" boolean) OWNER TO "postgres";

--
-- Name: find_pos_customer("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."find_pos_customer"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_query text := lower(trim(coalesce(p_query, '')));
  v_customer public.customers;
begin
  perform private.require_pos_staff();
  if position('@' in v_query) > 0 then
    select c.* into v_customer
    from public.customers c join auth.users u on u.id = c.id
    where lower(u.email) = v_query;
  elsif regexp_replace(v_query, '[^0-9]', '', 'g') ~ '^[0-9]{5,15}$' then
    select * into v_customer from public.customers
    where document_number = regexp_replace(v_query, '[^0-9]', '', 'g');
  end if;
  if v_customer.id is null then
    return null;
  end if;
  return jsonb_build_object(
    'id', v_customer.id,
    'full_name', coalesce(v_customer.business_name, v_customer.full_name),
    'customer_type', v_customer.customer_type,
    'wholesale_status', v_customer.wholesale_status
  );
end;
$_$;


ALTER FUNCTION "public"."find_pos_customer"("p_query" "text") OWNER TO "postgres";

--
-- Name: get_cart_items(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_cart_items"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    jsonb_agg(jsonb_build_object('product_id', ci.product_id, 'quantity', ci.quantity)
              order by ci.created_at),
    '[]'::jsonb
  )
  from public.cart_items ci
  join public.carts c on c.id = ci.cart_id
  where c.customer_id = auth.uid();
$$;


ALTER FUNCTION "public"."get_cart_items"() OWNER TO "postgres";

--
-- Name: get_catalog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_catalog"() RETURNS TABLE("product_id" "uuid", "sku" "text", "name" "text", "description" "text", "brand" "text", "volume_ml" integer, "origin" "public"."product_origin", "sale_unit" "text", "units_per_box" integer, "min_quantity" integer, "price_cop" bigint, "price_list_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with ctx as (
    select private.pricing_customer_type() as ptype,
           private.assigned_price_list_id() as assigned
  ),
  lists as (
    select
      -- Special list: only if it matches the sale type (a pending wholesale
      -- customer never gets wholesale prices) and RLS lets the caller see it.
      (select pl.id from public.price_lists pl, ctx
        where pl.id = ctx.assigned and pl.customer_type = ctx.ptype) as special_id,
      (select pl.id from public.price_lists pl, ctx
        where pl.is_default and pl.customer_type = ctx.ptype) as default_id
  )
  select
    p.id,
    p.sku,
    p.name,
    p.description,
    p.brand,
    p.volume_ml,
    p.origin,
    case when ctx.ptype = 'wholesale' then 'box' else 'unit' end,
    p.units_per_box,
    case when ctx.ptype = 'wholesale' then p.wholesale_min_boxes else p.retail_min_units end,
    coalesce(sp.price_cop, dp.price_cop),
    coalesce(sp.price_list_id, dp.price_list_id)
  from public.products p
  cross join ctx
  cross join lists
  left join public.product_prices sp
    on sp.product_id = p.id and sp.price_list_id = lists.special_id
  left join public.product_prices dp
    on dp.product_id = p.id and dp.price_list_id = lists.default_id
  where p.is_active
    and coalesce(sp.price_cop, dp.price_cop) is not null
    and (
      ctx.ptype = 'wholesale'
      or (p.allow_retail_by_unit and p.origin = 'national')
    )
  order by p.name, p.sku;
$$;


ALTER FUNCTION "public"."get_catalog"() OWNER TO "postgres";

--
-- Name: get_delivery_addresses(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_delivery_addresses"() RETURNS TABLE("id" "uuid", "label" "text", "address_line" "text", "details" "text", "zone_id" "uuid", "municipality" "text", "zone_active" boolean, "lat" double precision, "lng" double precision, "distance_m" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a.id, a.label, a.address_line, a.details, a.zone_id, z.municipality, z.is_active,
         extensions.st_y(a.location::extensions.geometry),
         extensions.st_x(a.location::extensions.geometry),
         private.distance_from_store_m(a.location)
  from public.customer_addresses a
  join public.delivery_zones z on z.id = a.zone_id
  where a.customer_id = auth.uid()
  order by a.created_at;
$$;


ALTER FUNCTION "public"."get_delivery_addresses"() OWNER TO "postgres";

--
-- Name: get_pickup_status("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_pickup_status"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'document_last3', d.document_last3,
    'locked', private.pickup_locked(d.failed_attempts),
    -- Only when set_pickup_document would accept it: the same rule as the
    -- panel's "without cédula" (private.pickups_needing_attention).
    'needs_document', exists (
      select 1 from private.pickups_needing_attention p where p.order_id = o.id and p.missing_document
    )
  )
  from public.orders o
  left join private.order_pickup_documents d on d.order_id = o.id
  where o.id = p_order_id
    and o.customer_id = (select auth.uid())
    and o.channel = 'web' and o.fulfillment = 'pickup';
$$;


ALTER FUNCTION "public"."get_pickup_status"("p_order_id" "uuid") OWNER TO "postgres";

--
-- Name: get_pos_catalog("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_pos_catalog"("p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_own text := current_setting('request.jwt.claims', true);
  v_claims jsonb;
  v_rows jsonb;
begin
  perform private.require_pos_staff();
  v_claims := private.pos_buyer_claims(p_customer_id);
  if v_claims is null then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  -- Priced as the buyer...
  perform set_config('request.jwt.claims', v_claims::text, true);
  select coalesce(jsonb_agg(jsonb_build_object(
    'product_id', c.product_id, 'sku', c.sku, 'name', c.name, 'sale_unit', c.sale_unit,
    'units_per_box', c.units_per_box, 'min_quantity', c.min_quantity, 'price_cop', c.price_cop
  ) order by c.name, c.sku), '[]'::jsonb)
  into v_rows
  from public.get_catalog() c;
  -- ...and the stock read back as the cashier.
  perform set_config('request.jwt.claims', v_own, true);

  return jsonb_build_object(
    'ok', true,
    'sale_unit', coalesce(v_rows #>> '{0,sale_unit}', 'unit'),
    'items', coalesce((
      select jsonb_agg(r || jsonb_build_object(
        'available_units', a.units,
        'available_sale_units', case when r ->> 'sale_unit' = 'box'
          then a.units / (r ->> 'units_per_box')::integer else a.units end
      ) order by ord)
      from jsonb_array_elements(v_rows) with ordinality as e(r, ord)
      cross join lateral (select private.pos_available_units((r ->> 'product_id')::uuid) as units) a
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_pos_catalog"("p_customer_id" "uuid") OWNER TO "postgres";

