-- Name: get_web_availability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_web_availability"() RETURNS TABLE("product_id" "uuid", "available_units" integer, "available_sale_units" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select
    c.product_id,
    private.web_available_units(c.product_id),
    case when c.sale_unit = 'box'
      then private.web_available_units(c.product_id) / c.units_per_box
      else private.web_available_units(c.product_id)
    end
  from public.get_catalog() c;
$$;


