--
-- Name: inventory_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."inventory_overview"() RETURNS TABLE("product_id" "uuid", "sku" "text", "name" "text", "origin" "public"."product_origin", "is_active" boolean, "units_per_box" integer, "on_hand" integer, "reserved" integer, "available" integer, "low_stock_threshold" integer, "web_safety_stock" integer, "is_low" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_staff(array['admin', 'warehouse']);
  return query
    select p.id, p.sku, p.name, p.origin, p.is_active, p.units_per_box,
      coalesce(s.on_hand, 0), coalesce(s.reserved, 0),
      coalesce(s.on_hand, 0) - coalesce(s.reserved, 0),
      p.low_stock_threshold, p.web_safety_stock,
      p.is_active and coalesce(s.on_hand, 0) - coalesce(s.reserved, 0) <= p.low_stock_threshold
    from public.products p
    left join public.product_stock s on s.product_id = p.id
    order by p.is_active desc, p.name;
end;
$$;


ALTER FUNCTION "public"."inventory_overview"() OWNER TO "postgres";

--
-- Name: inventory_recent_movements("uuid", boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."inventory_recent_movements"("p_product_id" "uuid" DEFAULT NULL::"uuid", "p_include_reservations" boolean DEFAULT false, "p_limit" integer DEFAULT 50) RETURNS TABLE("movement_id" "uuid", "created_at" timestamp with time zone, "product_id" "uuid", "sku" "text", "product_name" "text", "movement_type" "public"."inventory_movement_type", "units" integer, "reason" "text", "reference" "text", "recorded_by" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_staff(array['admin', 'warehouse']);
  return query
    select m.id, m.created_at, m.product_id, p.sku, p.name, m.movement_type, m.units, m.reason, m.reference,
      case when m.created_by is null then null
        else coalesce(
          (select i.full_name from public.staff_invitations i
           where i.user_id = m.created_by order by i.created_at desc limit 1),
          (select u.email::text from auth.users u where u.id = m.created_by)
        )
      end
    from public.inventory_movements m
    join public.products p on p.id = m.product_id
    where (p_product_id is null or m.product_id = p_product_id)
      and (p_include_reservations or m.movement_type not in ('reservation', 'reservation_release'))
    order by m.created_at desc, m.id
    limit least(greatest(coalesce(p_limit, 50), 1), 200);
end;
$$;


ALTER FUNCTION "public"."inventory_recent_movements"("p_product_id" "uuid", "p_include_reservations" boolean, "p_limit" integer) OWNER TO "postgres";

--
-- Name: invite_staff("text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."invite_staff"("p_email" "text", "p_full_name" "text", "p_phone" "text", "p_staff_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_email text := lower(trim(coalesce(p_email, '')));
  v_name text := trim(coalesce(p_full_name, ''));
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_resent boolean;
  v_id uuid;
  v_token text := encode(extensions.gen_random_bytes(32), 'hex');
begin
  perform private.require_admin();
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 254 then
    return jsonb_build_object('ok', false, 'error', 'invalid_email');
  end if;
  if length(v_name) not between 3 and 120 then
    return jsonb_build_object('ok', false, 'error', 'invalid_name');
  end if;
  if v_phone is not null and v_phone !~ '^[0-9+ ]{7,20}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_phone');
  end if;
  if p_staff_role is null or p_staff_role not in ('admin', 'cashier', 'courier', 'warehouse') then
    return jsonb_build_object('ok', false, 'error', 'invalid_role');
  end if;

  -- Resend: drop the earlier, never-opened invitation and its user.
  perform private.discard_unconfirmed_invitee(v_email);
  -- A real account (a customer, active or former staff) never becomes staff
  -- this way.
  if exists (select 1 from auth.users where lower(email) = v_email) then
    return jsonb_build_object('ok', false, 'error', 'email_has_account');
  end if;

  update public.staff_invitations set status = 'revoked', revoked_at = now()
  where email = v_email and status = 'pending';
  v_resent := found;

  insert into public.staff_invitations (email, full_name, phone, staff_role, token_hash, invited_by)
  values (v_email, v_name, v_phone, p_staff_role::public.staff_role,
          encode(extensions.digest(v_token, 'sha256'), 'hex'), auth.uid())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'invitation_id', v_id, 'email', v_email, 'token', v_token, 'resent', v_resent);
end;
$_$;


ALTER FUNCTION "public"."invite_staff"("p_email" "text", "p_full_name" "text", "p_phone" "text", "p_staff_role" "text") OWNER TO "postgres";

--
-- Name: low_stock_products(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."low_stock_products"() RETURNS TABLE("product_id" "uuid", "sku" "text", "name" "text", "on_hand" integer, "reserved" integer, "threshold" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_staff(array['admin', 'warehouse']);
  return query
    select p.id, p.sku, p.name, coalesce(s.on_hand, 0), coalesce(s.reserved, 0), p.low_stock_threshold
    from public.products p
    left join public.product_stock s on s.product_id = p.id
    where p.is_active and coalesce(s.on_hand, 0) - coalesce(s.reserved, 0) <= p.low_stock_threshold
    order by p.name;
end;
$$;


ALTER FUNCTION "public"."low_stock_products"() OWNER TO "postgres";

--
-- Name: mark_attempt_refunded("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."mark_attempt_refunded"("p_attempt_id" "uuid", "p_reference" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.payment_attempts;
  v_reference text := trim(coalesce(p_reference, ''));
  v_note text := trim(coalesce(p_note, ''));
begin
  perform private.require_admin();
  if length(v_reference) not between 3 and 120 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reference');
  end if;
  if length(v_note) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;
  select * into v_attempt from public.payment_attempts where id = p_attempt_id for update;
  if v_attempt.id is null or not v_attempt.refund_needed then
    return jsonb_build_object('ok', false, 'error', 'attempt_not_refundable');
  end if;
  if v_attempt.refunded_at is not null then
    return jsonb_build_object('ok', true, 'already_refunded', true);
  end if;
  update public.payment_attempts
  set refunded_at = now(), refunded_by = auth.uid(), refund_reference = v_reference, refund_note = v_note
  where id = p_attempt_id;
  insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
  select o.id, o.status, o.status, auth.uid(),
         'Pago duplicado reembolsado (' || v_reference || '): ' || v_note
  from public.orders o where o.id = v_attempt.order_id;
  return jsonb_build_object('ok', true, 'already_refunded', false);
end;
$$;


ALTER FUNCTION "public"."mark_attempt_refunded"("p_attempt_id" "uuid", "p_reference" "text", "p_note" "text") OWNER TO "postgres";

--
-- Name: mark_order_refunded("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."mark_order_refunded"("p_order_id" "uuid", "p_reference" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.orders;
  v_invoice public.invoices;
  v_reference text := trim(coalesce(p_reference, ''));
  v_note text := trim(coalesce(p_note, ''));
  v_credit_note uuid;
begin
  perform private.require_admin();
  if length(v_reference) not between 3 and 120 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reference');
  end if;
  if length(v_note) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null or not v_order.needs_refund then
    return jsonb_build_object('ok', false, 'error', 'order_not_refundable');
  end if;
  if v_order.refunded_at is not null then
    return jsonb_build_object('ok', true, 'already_refunded', true);
  end if;
  -- Any refund waits while the invoice is still being issued (as a POS void,
  -- D-053): otherwise Factus could accept it right after, with no credit
  -- note. "Being issued" means sent, or pending with its issue_invoice job
  -- still queued or running; a pending invoice whose job already ended
  -- (skipped, failed) does not block the refund forever, and a rejected one
  -- is final until someone retries it (retry_invoice makes it pending).
  select * into v_invoice from public.invoices where order_id = p_order_id for update;
  if v_invoice.status in ('pending', 'sent') and (
       v_invoice.status = 'sent'
       or exists (
         select 1 from public.actions a
         where a.idempotency_key = private.uuid_from_text('issue_invoice:' || p_order_id::text)
           and a.status in ('queued', 'processing')
       )
     ) then
    return jsonb_build_object('ok', false, 'error', 'invoice_in_progress', 'invoice_status', v_invoice.status);
  end if;

  update public.orders
  set refunded_at = now(), refunded_by = auth.uid(), refund_reference = v_reference, refund_note = v_note,
      -- A paid order, or one back at the store, becomes refunded; a
      -- cancelled one stays cancelled.
      status = case when status in ('paid', 'preparing') then 'refunded'::public.order_status else status end
  where id = p_order_id;

  -- That change is logged by the order history trigger; a cancelled order
  -- keeps its status, so the refund is logged here.
  if v_order.status not in ('paid', 'preparing') then
    insert into public.order_events (order_id, from_status, to_status, actor_id, reason)
    values (p_order_id, v_order.status, v_order.status, auth.uid(),
            'Reembolso registrado (' || v_reference || '): ' || v_note);
  end if;

  -- A whole refund annuls the invoice (concept 2); products only credits the
  -- product lines (concept 1), the delivery stays invoiced. A rejected
  -- invoice is not a valid document: no credit note.
  if v_invoice.status = 'accepted' then
    v_credit_note := private.request_credit_note_kind(
      v_invoice.id, 'Reembolso: ' || v_note,
      case when v_order.refund_amount_cop is not null then 'products_only' else 'full' end);
  end if;
  return jsonb_build_object('ok', true, 'already_refunded', false, 'credit_note_id', v_credit_note);
end;
$$;


ALTER FUNCTION "public"."mark_order_refunded"("p_order_id" "uuid", "p_reference" "text", "p_note" "text") OWNER TO "postgres";

--
-- Name: order_email_data("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."order_email_data"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'order_id', o.id,
    'email', u.email,
    'customer_name', c.full_name,
    'status', o.status,
    'fulfillment', o.fulfillment,
    'subtotal_cop', o.subtotal_cop,
    'delivery_fee_cop', o.delivery_fee_cop,
    'total_cop', o.total_cop,
    'refund_amount_cop', o.refund_amount_cop,
    'return_kind', o.delivery_return_kind,
    'return_choice_deadline', o.return_choice_deadline,
    'scheduled_delivery_on', o.scheduled_delivery_on,
    'address_line', o.delivery_address ->> 'address_line',
    'municipality', o.delivery_address ->> 'municipality',
    'failure_reason', (
      select a.failure_reason from public.delivery_attempts a
      where a.order_id = o.id and a.outcome = 'failed'
      order by a.created_at desc limit 1
    )
  )
  from public.orders o
  join public.customers c on c.id = o.customer_id
  join auth.users u on u.id = o.customer_id
  where o.id = p_order_id;
$$;


ALTER FUNCTION "public"."order_email_data"("p_order_id" "uuid") OWNER TO "postgres";

--
-- Name: payments_to_reconcile(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."payments_to_reconcile"("p_min_age_minutes" integer DEFAULT 15, "p_limit" integer DEFAULT 50) RETURNS TABLE("attempt_id" "uuid", "transaction_id" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.payment_attempts pa
  set status = 'abandoned', finalized_at = now()
  from public.orders o
  where o.id = pa.order_id
    and pa.status = 'pending'
    and pa.wompi_transaction_id is null
    and o.status <> 'awaiting_payment'
    and coalesce(o.cancelled_at, o.paid_at, o.created_at) < now() - interval '48 hours';

  with picked as (
    select pa.id
    from public.payment_attempts pa
    where pa.status = 'pending'
      and coalesce(pa.wompi_transaction_id, pa.transaction_id_hint) is not null
      and pa.created_at <= now() - make_interval(mins => p_min_age_minutes)
    order by pa.last_reconciled_at nulls first, pa.created_at, pa.id
    limit greatest(coalesce(p_limit, 50), 0)
    for update of pa skip locked
  )
  update public.payment_attempts pa
  set last_reconciled_at = now()
  from picked
  where pa.id = picked.id
  returning pa.id, coalesce(pa.wompi_transaction_id, pa.transaction_id_hint);
$$;


ALTER FUNCTION "public"."payments_to_reconcile"("p_min_age_minutes" integer, "p_limit" integer) OWNER TO "postgres";

--
-- Name: place_order("uuid", "public"."fulfillment_method", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."place_order"("p_idempotency_key" "uuid", "p_fulfillment" "public"."fulfillment_method" DEFAULT 'pickup'::"public"."fulfillment_method", "p_address_id" "uuid" DEFAULT NULL::"uuid", "p_pickup_document" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_detail text;
begin
  return private.create_web_order(p_idempotency_key, p_fulfillment, p_address_id, p_pickup_document);
exception when sqlstate '22023' then
  get stacked diagnostics v_detail = pg_exception_detail;
  if sqlerrm = 'inventory_insufficient_stock' then
    return jsonb_build_object('ok', false, 'error', 'insufficient_stock', 'product_id', v_detail);
  end if;
  if sqlerrm = 'order_delivery_unavailable' then
    return jsonb_build_object('ok', false, 'error', 'delivery_unavailable', 'reason', v_detail);
  end if;
  if sqlerrm = 'sales_blocked' then
    -- Nothing was created and the cart stays as it was.
    return jsonb_build_object('ok', false, 'error', 'sales_blocked', 'block', v_detail::jsonb);
  end if;
  raise;
end;
$$;


ALTER FUNCTION "public"."place_order"("p_idempotency_key" "uuid", "p_fulfillment" "public"."fulfillment_method", "p_address_id" "uuid", "p_pickup_document" "text") OWNER TO "postgres";

--
-- Name: prepare_invoice("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."prepare_invoice"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.orders;
  v_invoice public.invoices;
  v_customer public.customers;
  v_email text;
  v_method text;
  v_item record;
  v_tax record;
  v_buyer jsonb;
  v_totals record;
  v_iva numeric := private.setting_integer('iva_rate_pct', 5)::numeric / 100;
  v_fee_base bigint;
begin
  select * into v_invoice from public.invoices where order_id = p_order_id;

  -- A voided POS sale: an invoice that was not accepted can never be sent
  -- (it would be accepted without a credit note).
  if v_invoice.id is not null and v_invoice.status <> 'accepted'
     and exists (select 1 from public.orders where id = p_order_id and voided_at is not null) then
    raise exception 'invoice_order_not_invoiceable' using errcode = '22023';
  end if;

  if v_invoice.id is null then
    select * into v_order from public.orders where id = p_order_id for update;
    if v_order.id is null or v_order.status not in ('paid', 'preparing', 'out_for_delivery', 'delivered')
       or v_order.needs_refund then
      raise exception 'invoice_order_not_invoiceable' using errcode = '22023';
    end if;

    select * into v_customer from public.customers where id = v_order.customer_id;
    select email into v_email from auth.users where id = v_order.customer_id;

    -- Buyer (D-044, PROJECT ASSUMPTIONS): wholesale with NIT; everybody else
    -- as "consumidor final" with their email.
    if v_customer.customer_type = 'wholesale' and v_customer.document_type = 'nit' then
      v_buyer := jsonb_build_object(
        'kind', 'company',
        'nit', v_customer.document_number,
        'company', coalesce(v_customer.business_name, v_customer.full_name),
        'email', v_email,
        'phone', v_customer.phone
      );
    else
      v_buyer := jsonb_build_object(
        'kind', 'final_consumer',
        'names', 'Consumidor final',
        'email', v_email
      );
    end if;

    if v_order.channel = 'pos' then
      v_method := 'POS_' || upper(v_order.pos_payment_method);
    else
      select coalesce(a.payment_method_type, 'UNKNOWN') into v_method
      from public.payment_attempts a
      -- A duplicate payment (D-072) is refunded: never its method.
      where a.order_id = p_order_id and a.status = 'approved' and not a.refund_needed
      order by a.finalized_at desc limit 1;
    end if;

    insert into public.invoices (
      order_id, reference_code, customer, payment_method_code,
      total_cop, iva_cop, participation_cop, exploitation_cop, base_cop
    ) values (
      p_order_id,
      'INV-' || upper(replace(p_order_id::text, '-', '')),
      v_buyer,
      coalesce(v_method, 'UNKNOWN'),
      v_order.total_cop, 0, 0, 0, v_order.total_cop
    )
    returning * into v_invoice;

    for v_item in
      select oi.*, oi.base_units as units from public.order_items oi where oi.order_id = p_order_id
    loop
      select * into v_tax from private.tax_breakdown(v_item.product_id, v_item.units, v_item.line_total_cop);
      insert into public.invoice_lines (
        invoice_id, product_id, sku, name, quantity_units, final_cop,
        base_cop, specific_cop, ad_valorem_cop, exploitation_cop, iva_cop
      ) values (
        v_invoice.id, v_item.product_id, v_item.sku, v_item.product_name, v_item.units,
        v_item.line_total_cop, v_tax.base_cop, v_tax.specific_cop, v_tax.ad_valorem_cop,
        v_tax.exploitation_cop, v_tax.iva_cop
      );
    end loop;

    if v_order.delivery_fee_cop > 0 then
      v_fee_base := round(v_order.delivery_fee_cop / (1 + v_iva));
      insert into public.invoice_lines (
        invoice_id, product_id, line_kind, sku, name, quantity_units, final_cop,
        base_cop, specific_cop, ad_valorem_cop, exploitation_cop, iva_cop
      ) values (
        v_invoice.id, null, 'delivery', 'DOMICILIO', 'Servicio de domicilio', 1,
        v_order.delivery_fee_cop, v_fee_base, 0, 0, 0, v_order.delivery_fee_cop - v_fee_base
      );
    end if;

    select sum(base_cop) b, sum(specific_cop + ad_valorem_cop) p, sum(exploitation_cop) e, sum(iva_cop) i
    into v_totals from public.invoice_lines where invoice_id = v_invoice.id;

    update public.invoices
    set base_cop = v_totals.b, participation_cop = v_totals.p,
        exploitation_cop = v_totals.e, iva_cop = v_totals.i
    where id = v_invoice.id
    returning * into v_invoice;
  end if;

  return to_jsonb(v_invoice) || jsonb_build_object(
    'lines', (select jsonb_agg(to_jsonb(l) order by l.line_kind desc, l.sku) from public.invoice_lines l where l.invoice_id = v_invoice.id)
  );
end;
$$;


ALTER FUNCTION "public"."prepare_invoice"("p_order_id" "uuid") OWNER TO "postgres";

--
-- Name: quote_delivery("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."quote_delivery"("p_address_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_items jsonb;
  v_quote jsonb;
begin
  if v_uid is null or not exists (select 1 from public.customers where id = v_uid) then
    raise exception 'delivery_requires_customer' using errcode = '42501';
  end if;
  v_items := public.get_cart_items();
  if jsonb_array_length(v_items) = 0 then
    return jsonb_build_object('ok', false, 'error', 'cart_empty');
  end if;
  v_quote := public.quote_items(v_items);
  if not (v_quote ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', 'quote_failed');
  end if;
  return private.delivery_quote(
    p_address_id, v_uid, v_quote ->> 'sale_unit', (v_quote ->> 'total_boxes')::integer
  );
end;
$$;


ALTER FUNCTION "public"."quote_delivery"("p_address_id" "uuid") OWNER TO "postgres";

--
-- Name: quote_items("jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."quote_items"("p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_sale_unit text := case
    when private.pricing_customer_type() = 'wholesale' then 'box' else 'unit' end;
  v_item jsonb;
  v_index integer := 0;
  v_product_id uuid;
  v_quantity integer;
  v_error text;
  v_row record;
  v_min integer;
  v_seen uuid[] := array[]::uuid[];
  v_lines jsonb := '[]'::jsonb;
  v_total bigint := 0;
  v_boxes integer := 0;
  v_base_units integer := 0;
  v_ok boolean := true;
begin
  if jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 100 then
    raise exception 'quote_invalid_items' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_index := v_index + 1;
    v_error := null;
    v_product_id := null;
    v_quantity := null;
    v_min := null;

    if jsonb_typeof(v_item -> 'product_id') = 'string'
       and (v_item ->> 'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_product_id := (v_item ->> 'product_id')::uuid;
    else
      v_error := 'invalid_product';
    end if;

    if v_error is null then
      if jsonb_typeof(v_item -> 'quantity') = 'number'
         and (v_item ->> 'quantity') ~ '^[0-9]{1,5}$'
         and (v_item ->> 'quantity')::integer between 1 and 10000 then
        v_quantity := (v_item ->> 'quantity')::integer;
      else
        v_error := 'invalid_quantity';
      end if;
    end if;

    if v_error is null and v_product_id = any (v_seen) then
      v_error := 'duplicate_product';
    end if;

    if v_error is null then
      v_seen := v_seen || v_product_id;
      select * into v_row from public.get_catalog() c where c.product_id = v_product_id;
      if not found then
        v_error := 'product_unavailable';
      else
        v_min := v_row.min_quantity;
        if v_quantity < v_min then
          v_error := 'below_minimum';
        end if;
      end if;
    end if;

    if v_error is null then
      v_total := v_total + v_row.price_cop * v_quantity;
      if v_sale_unit = 'box' then
        v_boxes := v_boxes + v_quantity;
        v_base_units := v_base_units + v_quantity * v_row.units_per_box;
      else
        v_base_units := v_base_units + v_quantity;
      end if;
      v_lines := v_lines || jsonb_build_object(
        'index', v_index,
        'product_id', v_product_id,
        'quantity', v_quantity,
        'unit_price_cop', v_row.price_cop,
        'line_total_cop', v_row.price_cop * v_quantity,
        'base_units', case when v_sale_unit = 'box'
                           then v_quantity * v_row.units_per_box else v_quantity end,
        'min_quantity', v_min,
        'error', null
      );
    else
      v_ok := false;
      v_lines := v_lines || jsonb_build_object(
        'index', v_index,
        'product_id', v_product_id,
        'quantity', v_quantity,
        'unit_price_cop', null,
        'line_total_cop', null,
        'base_units', null,
        'min_quantity', v_min,
        'error', v_error
      );
    end if;
  end loop;

  return jsonb_build_object(
    'ok', v_ok,
    'sale_unit', v_sale_unit,
    'total_cop', case when v_ok then v_total else null end,
    'total_boxes', case when v_ok then v_boxes else null end,
    'total_base_units', case when v_ok then v_base_units else null end,
    'lines', v_lines
  );
end;
$_$;


ALTER FUNCTION "public"."quote_items"("p_items" "jsonb") OWNER TO "postgres";

--
-- Name: reconcile_stock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reconcile_stock"() RETURNS TABLE("product_id" "uuid", "on_hand" integer, "ledger_on_hand" bigint, "reserved" integer, "ledger_reserved" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select s.product_id, s.on_hand, coalesce(m.on_hand, 0), s.reserved, coalesce(m.reserved, 0)
  from public.product_stock s
  left join (
    select product_id,
      sum(units) filter (where movement_type not in ('reservation', 'reservation_release')) as on_hand,
      sum(units) filter (where movement_type in ('reservation', 'reservation_release')) as reserved
    from public.inventory_movements group by product_id
  ) m on m.product_id = s.product_id
  where s.on_hand <> coalesce(m.on_hand, 0) or s.reserved <> coalesce(m.reserved, 0);
$$;


ALTER FUNCTION "public"."reconcile_stock"() OWNER TO "postgres";

--
-- Name: record_count("uuid", integer, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_count"("p_product_id" "uuid", "p_counted_units" integer, "p_reason" "text", "p_idempotency_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_stock public.product_stock;
  v_diff integer;
begin
  perform private.require_staff(array['admin', 'warehouse']);
  v_id := private.inventory_movement_for_key(p_idempotency_key, p_product_id, 'adjustment');
  if v_id is not null then return v_id; end if;
  if p_counted_units is null or p_counted_units < 0 or p_counted_units > 1000000 then
    perform private.inventory_error('invalid_units');
  end if;
  if length(trim(coalesce(p_reason, ''))) = 0 then perform private.inventory_error('missing_reason'); end if;
  if length(trim(p_reason)) > 300 then perform private.inventory_error('invalid_reason'); end if;

  v_stock := private.lock_stock(p_product_id);
  -- Without this second check, a simultaneous submission with the same key
  -- would see the corrected stock and answer "no difference".
  v_id := private.inventory_movement_for_key(p_idempotency_key, p_product_id, 'adjustment');
  if v_id is not null then return v_id; end if;

  if p_counted_units < v_stock.reserved then
    perform private.inventory_error('count_below_reserved');
  end if;
  v_diff := p_counted_units - v_stock.on_hand;
  if v_diff = 0 then return null; end if;

  insert into public.inventory_movements
    (product_id, movement_type, units, reason, created_by, idempotency_key)
  values
    (p_product_id, 'adjustment', v_diff, trim(p_reason), auth.uid(), p_idempotency_key)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_count"("p_product_id" "uuid", "p_counted_units" integer, "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: record_credit_note_result("uuid", "text", "jsonb", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_credit_note_result"("p_credit_note_id" "uuid", "p_outcome" "text", "p_request" "jsonb", "p_response" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.credit_notes
  set attempts = attempts + 1,
      request = coalesce(p_request, request),
      response = coalesce(p_response, response),
      last_error = p_error,
      status = case p_outcome
        when 'accepted' then 'accepted'::public.invoice_status
        when 'rejected' then 'rejected'::public.invoice_status
        when 'sent' then 'sent'::public.invoice_status
        else status end,
      factus_number = coalesce(p_response #>> '{data,number}', factus_number),
      cufe = coalesce(p_response #>> '{data,cufe}', cufe)
  where id = p_credit_note_id and status <> 'accepted';
$$;


ALTER FUNCTION "public"."record_credit_note_result"("p_credit_note_id" "uuid", "p_outcome" "text", "p_request" "jsonb", "p_response" "jsonb", "p_error" "text") OWNER TO "postgres";

--
-- Name: record_delivery_attempt("uuid", "uuid", "uuid", "public"."delivery_outcome", "text", "text", boolean, "text", "text", "text", double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_delivery_attempt"("p_idempotency_key" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_outcome" "public"."delivery_outcome", "p_recipient_name" "text", "p_document_number" "text", "p_age_confirmed" boolean, "p_signature_path" "text", "p_failure_reason" "text", "p_notes" "text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_existing public.delivery_attempts;
  v_order public.orders;
  v_role text := private.user_staff_role(p_actor_id);
  v_attempt_id uuid;
  v_location extensions.geography;
  v_name text := trim(coalesce(p_recipient_name, ''));
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
  v_kind text;
begin
  select * into v_existing from public.delivery_attempts where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.order_id <> p_order_id or v_existing.actor_id <> p_actor_id then
      raise exception 'idempotency_key_conflict' using errcode = 'P0001';
    end if;
    return jsonb_build_object('ok', true, 'duplicate', true,
                              'attempt_id', v_existing.id, 'outcome', v_existing.outcome);
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null or v_order.fulfillment <> 'delivery' or v_order.status <> 'out_for_delivery' then
    return jsonb_build_object('ok', false, 'error', 'order_not_out_for_delivery');
  end if;
  if not (v_role = 'admin' or (v_role = 'courier' and v_order.courier_id = p_actor_id)) then
    return jsonb_build_object('ok', false, 'error', 'delivery_forbidden');
  end if;
  if v_notes is not null and length(v_notes) > 500 then
    return jsonb_build_object('ok', false, 'error', 'invalid_notes');
  end if;
  if p_lat is not null and p_lng is not null
     and p_lat between -90 and 90 and p_lng between -180 and 180 then
    v_location := private.make_point(p_lat, p_lng);
  end if;

  if p_outcome = 'failed' then
    v_kind := private.delivery_failure_kind(p_failure_reason);
    if v_kind is null then
      return jsonb_build_object('ok', false, 'error', 'invalid_failure_reason');
    end if;
    insert into public.delivery_attempts
      (order_id, actor_id, outcome, failure_reason, notes, location, idempotency_key)
    values (p_order_id, p_actor_id, 'failed', p_failure_reason, v_notes, v_location, p_idempotency_key)
    returning id into v_attempt_id;

    -- Back to the store, without assignment (D-059). The history says who and why.
    perform private.set_order_event_context(
      p_actor_id, 'Entrega fallida: ' || p_failure_reason || coalesce(' — ' || v_notes, ''));
    update public.orders
    set status = 'preparing',
        delivery_provider_id = null, courier_id = null, delivery_external_ref = null, assigned_at = null,
        delivery_return_kind = v_kind, returned_at = now(),
        return_choice = null, return_choice_at = null, return_choice_defaulted = false,
        return_choice_deadline = case when v_kind = 'customer' then now() + interval '3 days' end,
        scheduled_delivery_on = case when v_kind = 'force_majeure' then private.bogota_tomorrow() end,
        needs_refund = needs_refund or v_kind = 'underage',
        refund_reason = case when v_kind = 'underage' then 'recipient_underage' else refund_reason end,
        refund_amount_cop = case when v_kind = 'underage' then subtotal_cop else refund_amount_cop end
    where id = p_order_id;

    perform private.set_order_event_context(null, null);
    if v_kind = 'underage' then
      -- The bottles are back at the store and can be sold again (D-069).
      perform private.return_order_stock(p_order_id, 'Domicilio fallido: menor de edad', p_actor_id);
    end if;
    perform private.enqueue_order_email('delivery_' || v_kind, p_order_id, v_attempt_id::text);

    return jsonb_build_object('ok', true, 'duplicate', false, 'attempt_id', v_attempt_id, 'outcome', 'failed');
  end if;

  -- Delivered: every piece of the proof is required (D-007).
  if p_age_confirmed is distinct from true then
    return jsonb_build_object('ok', false, 'error', 'age_not_confirmed');
  end if;
  if length(v_name) not between 3 and 120 then
    return jsonb_build_object('ok', false, 'error', 'invalid_recipient_name');
  end if;
  if coalesce(p_document_number, '') !~ '^[0-9]{5,12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_document_number');
  end if;
  if p_signature_path is distinct from (p_order_id::text || '/' || p_idempotency_key::text || '.png')
     or not exists (
       select 1 from storage.objects
       where bucket_id = 'delivery-signatures' and name = p_signature_path
     ) then
    return jsonb_build_object('ok', false, 'error', 'signature_missing');
  end if;

  insert into public.delivery_attempts
    (order_id, actor_id, outcome, failure_reason, notes, location, idempotency_key)
  values (p_order_id, p_actor_id, 'delivered', null, v_notes, v_location, p_idempotency_key)
  returning id into v_attempt_id;

  insert into public.delivery_proofs (
    order_id, attempt_id, recipient_name, recipient_document_number,
    age_confirmed, signature_path, delivered_by
  ) values (
    p_order_id, v_attempt_id, v_name, p_document_number, true, p_signature_path, p_actor_id
  );

  perform private.set_order_event_context(p_actor_id, null);
  -- The return of an earlier attempt stays as history; the schedule is done.
  update public.orders
  set status = 'delivered', delivered_at = now(), scheduled_delivery_on = null
  where id = p_order_id;
  perform private.set_order_event_context(null, null);

  return jsonb_build_object('ok', true, 'duplicate', false, 'attempt_id', v_attempt_id, 'outcome', 'delivered');
end;
$_$;


ALTER FUNCTION "public"."record_delivery_attempt"("p_idempotency_key" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_outcome" "public"."delivery_outcome", "p_recipient_name" "text", "p_document_number" "text", "p_age_confirmed" boolean, "p_signature_path" "text", "p_failure_reason" "text", "p_notes" "text", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";

--
-- Name: record_invoice_result("uuid", "text", "jsonb", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_invoice_result"("p_invoice_id" "uuid", "p_outcome" "text", "p_request" "jsonb", "p_response" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_data jsonb := p_response -> 'data';
begin
  update public.invoices
  set attempts = attempts + 1,
      request = coalesce(p_request, request),
      response = coalesce(p_response, response),
      last_error = p_error,
      sent_at = coalesce(sent_at, now()),
      status = case p_outcome
        when 'accepted' then 'accepted'::public.invoice_status
        when 'rejected' then 'rejected'::public.invoice_status
        when 'sent' then 'sent'::public.invoice_status
        else status end,
      factus_number = coalesce(v_data ->> 'number', factus_number),
      cufe = coalesce(v_data ->> 'cufe', cufe),
      qr_url = coalesce(v_data #>> '{links,qr}', qr_url),
      public_url = coalesce(v_data #>> '{links,public_url}', public_url),
      dian_errors = coalesce(v_data -> 'errors', dian_errors),
      accepted_at = case when p_outcome = 'accepted' then now() else accepted_at end,
      rejected_at = case when p_outcome = 'rejected' then now() else rejected_at end
  where id = p_invoice_id
    -- An accepted invoice never changes.
    and status <> 'accepted';
end;
$$;


ALTER FUNCTION "public"."record_invoice_result"("p_invoice_id" "uuid", "p_outcome" "text", "p_request" "jsonb", "p_response" "jsonb", "p_error" "text") OWNER TO "postgres";

--
-- Name: record_payment_redirect("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_payment_redirect"("p_order_id" "uuid", "p_transaction_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
begin
  if p_transaction_id is null or p_transaction_id !~ '^[0-9A-Za-z-]{6,64}$' then
    return;
  end if;
  -- RLS: only the customer's own order.
  if exists (select 1 from public.orders where id = p_order_id and customer_id = auth.uid()) then
    perform private.store_transaction_hint(p_order_id, p_transaction_id);
  end if;
end;
$_$;


