--
-- Name: request_credit_note("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."request_credit_note"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_invoice public.invoices;
  v_id uuid;
begin
  if not (private.is_service_role() or private.has_staff_role(array['admin'])) then
    raise exception 'credit_note_forbidden' using errcode = '42501';
  end if;
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.status <> 'accepted' then
    raise exception 'credit_note_invoice_not_accepted' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'credit_note_missing_reason' using errcode = '22023';
  end if;

  insert into public.credit_notes (invoice_id, reference_code, reason, requested_by)
  values (p_invoice_id, 'NC-' || upper(replace(p_invoice_id::text, '-', '')), trim(p_reason), auth.uid())
  on conflict (invoice_id) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.credit_notes where invoice_id = p_invoice_id;
    return v_id;
  end if;

  perform public.enqueue_action(
    private.uuid_from_text('issue_credit_note:' || v_id::text),
    'issue_credit_note', null, jsonb_build_object('credit_note_id', v_id), 8
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."request_credit_note"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: reserve_stock("text", "jsonb", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reserve_stock"("p_reference" "text", "p_items" "jsonb", "p_ttl_minutes" integer DEFAULT NULL::integer) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_units integer;
  v_ttl integer;
  v_stock public.product_stock;
  v_safety integer;
  v_reservation_id uuid;
begin
  perform private.require_staff(array['admin']);
  if length(trim(coalesce(p_reference, ''))) = 0 then perform private.inventory_error('missing_reference'); end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    perform private.inventory_error('invalid_items');
  end if;

  v_ttl := coalesce(
    p_ttl_minutes,
    (select (value #>> '{}')::integer from public.app_settings where key = 'reservation_ttl_minutes'),
    30
  );

  -- Lock in a stable order (by product id) to avoid deadlocks between two
  -- reservations that share products.
  for v_item in
    select value from jsonb_array_elements(p_items) order by value ->> 'product_id'
  loop
    v_product_id := (v_item ->> 'product_id')::uuid;
    v_units := (v_item ->> 'units')::integer;
    if v_units is null or v_units <= 0 then perform private.inventory_error('invalid_units'); end if;

    v_stock := private.lock_stock(v_product_id);
    select web_safety_stock into v_safety from public.products where id = v_product_id;
    if v_stock.on_hand - v_stock.reserved - v_safety < v_units then
      -- Aborts the whole transaction: nothing stays reserved.
      raise exception 'inventory_insufficient_stock'
        using errcode = '22023', detail = v_product_id::text;
    end if;

    insert into public.stock_reservations (product_id, units, reference, expires_at, created_by)
    values (v_product_id, v_units, trim(p_reference), now() + make_interval(mins => v_ttl), auth.uid())
    returning id into v_reservation_id;

    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reservation_id, created_by)
    values
      (v_product_id, 'reservation', v_units, trim(p_reference), v_reservation_id, auth.uid());

    return next v_reservation_id;
  end loop;
end;
$$;


ALTER FUNCTION "public"."reserve_stock"("p_reference" "text", "p_items" "jsonb", "p_ttl_minutes" integer) OWNER TO "postgres";

--
-- Name: retry_action("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."retry_action"("p_action_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_admin();
  if exists (
    select 1 from public.actions
    where id = p_action_id
      and type = 'confirm_delivery'
      and payload ->> 'outcome' = 'delivered'
      and not (payload ? 'document_number' and payload ? 'recipient_name')
  ) then
    return jsonb_build_object('ok', false, 'error', 'delivery_proof_data_removed');
  end if;
  return private.requeue_action(p_action_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."retry_action"("p_action_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: retry_credit_note("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."retry_credit_note"("p_credit_note_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_note public.credit_notes;
  v_result jsonb;
begin
  perform private.require_admin();
  select * into v_note from public.credit_notes where id = p_credit_note_id for update;
  if v_note.id is null then
    return jsonb_build_object('ok', false, 'error', 'credit_note_not_found');
  end if;
  if v_note.status = 'accepted' then
    return jsonb_build_object('ok', false, 'error', 'credit_note_accepted');
  end if;
  v_result := private.requeue_action(
    private.action_id_by_key(private.uuid_from_text('issue_credit_note:' || v_note.id::text)), p_reason);
  if not (v_result ->> 'ok')::boolean then
    return v_result;
  end if;
  update public.credit_notes set status = 'pending', last_error = null where id = p_credit_note_id;
  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."retry_credit_note"("p_credit_note_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: retry_invoice("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."retry_invoice"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_invoice public.invoices;
  v_order public.orders;
  v_result jsonb;
  v_action_id uuid;
begin
  perform private.require_admin();
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if v_invoice.id is null then
    return jsonb_build_object('ok', false, 'error', 'invoice_not_found');
  end if;
  if v_invoice.status = 'accepted' then
    return jsonb_build_object('ok', false, 'error', 'invoice_accepted');
  end if;
  select * into v_order from public.orders where id = v_invoice.order_id;
  if v_order.voided_at is not null or v_order.needs_refund then
    return jsonb_build_object('ok', false, 'error', 'order_not_invoiceable');
  end if;

  v_result := private.requeue_action(
    private.action_id_by_key(private.uuid_from_text('issue_invoice:' || v_invoice.order_id::text)), p_reason);
  if v_result ->> 'error' = 'action_not_found' then
    -- Defensive: the action should exist. Issue it with the same derived
    -- key the trigger uses, so the panel and later retries find it.
    select tracking_id into v_action_id from public.enqueue_action(
      private.uuid_from_text('issue_invoice:' || v_invoice.order_id::text), 'issue_invoice', null,
      jsonb_build_object('order_id', v_invoice.order_id), 8);
    insert into public.action_retries (action_id, action_type, previous_error, reason, retried_by)
    values (v_action_id, 'issue_invoice', 'action_not_found', trim(p_reason), auth.uid());
  elsif not (v_result ->> 'ok')::boolean then
    return v_result;
  end if;

  update public.invoices set status = 'pending', last_error = null where id = p_invoice_id;
  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."retry_invoice"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: review_wholesale("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."review_wholesale"("p_customer_id" "uuid", "p_decision" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_customer public.customers;
  v_reason text := trim(coalesce(p_reason, ''));
begin
  perform private.require_admin();
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('ok', false, 'error', 'invalid_decision');
  end if;
  if length(v_reason) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;

  select * into v_customer from public.customers where id = p_customer_id for update;
  if v_customer.id is null or v_customer.customer_type <> 'wholesale' then
    return jsonb_build_object('ok', false, 'error', 'not_wholesale');
  end if;

  if v_customer.wholesale_status::text = p_decision then
    return jsonb_build_object('ok', false, 'error', 'no_change');
  end if;

  update public.customers set wholesale_status = p_decision::public.wholesale_status where id = p_customer_id;
  update auth.users
  set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)
    || jsonb_build_object('wholesale_approved', p_decision = 'approved')
  where id = p_customer_id;
  insert into public.wholesale_reviews (customer_id, decision, reason, reviewed_by)
  values (p_customer_id, p_decision::public.wholesale_status, v_reason, auth.uid());
  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;


ALTER FUNCTION "public"."review_wholesale"("p_customer_id" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";

