-- Name: revoke_staff_invitation("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."revoke_staff_invitation"("p_invitation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text;
begin
  perform private.require_admin();
  update public.staff_invitations set status = 'revoked', revoked_at = now()
  where id = p_invitation_id and status = 'pending'
  returning email into v_email;
  if v_email is null then
    return false;
  end if;
  perform private.discard_unconfirmed_invitee(v_email);
  return true;
end;
$$;


