--
-- Name: save_delivery_address("text", "text", "text", "uuid", double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_delivery_address"("p_label" "text", "p_address_line" "text", "p_details" "text", "p_zone_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_location extensions.geography;
  v_label text := trim(coalesce(p_label, ''));
  v_line text := trim(coalesce(p_address_line, ''));
  v_details text := nullif(trim(coalesce(p_details, '')), '');
  v_id uuid;
begin
  if v_uid is null or not exists (select 1 from public.customers where id = v_uid) then
    raise exception 'address_requires_customer' using errcode = '42501';
  end if;
  if length(v_label) not between 1 and 60 or length(v_line) not between 5 and 200
     or length(coalesce(v_details, '')) > 200 then
    raise exception 'address_invalid_field' using errcode = '22023';
  end if;
  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'address_invalid_location' using errcode = '22023';
  end if;
  if not exists (select 1 from public.delivery_zones where id = p_zone_id and is_active) then
    raise exception 'address_zone_not_available' using errcode = '22023';
  end if;

  v_location := private.make_point(p_lat, p_lng);
  if private.store_location() is null
     or private.distance_from_store_m(v_location) > private.setting_integer('delivery_max_distance_m', 30000) then
    raise exception 'address_out_of_range' using errcode = '22023';
  end if;

  if (select count(*) from public.customer_addresses where customer_id = v_uid) >= 10 then
    raise exception 'address_too_many' using errcode = '22023';
  end if;

  insert into public.customer_addresses (customer_id, label, address_line, details, zone_id, location)
  values (v_uid, v_label, v_line, v_details, p_zone_id, v_location)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."save_delivery_address"("p_label" "text", "p_address_line" "text", "p_details" "text", "p_zone_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";

--
-- Name: set_cart_item("uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_cart_item"("p_product_id" "uuid", "p_quantity" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_cart_id uuid;
begin
  if v_uid is null or not exists (select 1 from public.customers where id = v_uid) then
    raise exception 'cart_requires_customer' using errcode = '42501';
  end if;
  if p_quantity is null or p_quantity < 0 or p_quantity > 10000 then
    raise exception 'cart_invalid_quantity' using errcode = '22023';
  end if;
  if not exists (select 1 from public.products where id = p_product_id and is_active) then
    raise exception 'cart_unknown_product' using errcode = '22023';
  end if;

  insert into public.carts (customer_id) values (v_uid)
  on conflict (customer_id) do update set updated_at = now()
  returning id into v_cart_id;

  if p_quantity = 0 then
    delete from public.cart_items where cart_id = v_cart_id and product_id = p_product_id;
    return;
  end if;

  if (select count(*) from public.cart_items where cart_id = v_cart_id and product_id <> p_product_id) >= 100 then
    raise exception 'cart_too_many_items' using errcode = '22023';
  end if;

  insert into public.cart_items (cart_id, product_id, quantity)
  values (v_cart_id, p_product_id, p_quantity)
  on conflict (cart_id, product_id) do update set quantity = excluded.quantity;
end;
$$;


ALTER FUNCTION "public"."set_cart_item"("p_product_id" "uuid", "p_quantity" integer) OWNER TO "postgres";

--
-- Name: set_pickup_document("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_pickup_document"("p_order_id" "uuid", "p_document" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders;
  v_digits text;
begin
  if v_uid is null then
    raise exception 'pickup_requires_customer' using errcode = '42501';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found or v_order.customer_id is distinct from v_uid then
    return jsonb_build_object('ok', false, 'error', 'order_not_found');
  end if;
  if v_order.channel <> 'web' or v_order.fulfillment <> 'pickup'
     or v_order.status not in ('paid', 'preparing') or v_order.needs_refund
     or exists (select 1 from public.pickup_confirmations where order_id = p_order_id) then
    return jsonb_build_object('ok', false, 'error', 'pickup_not_available');
  end if;
  if exists (select 1 from public.customers where id = v_uid and document_type = 'nit') then
    return jsonb_build_object('ok', false, 'error', 'not_needed');
  end if;
  if exists (select 1 from private.order_pickup_documents where order_id = p_order_id and document_hash is not null) then
    return jsonb_build_object('ok', false, 'error', 'document_already_set');
  end if;
  v_digits := private.normalize_id_document(p_document);
  if v_digits is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_pickup_document');
  end if;
  insert into private.order_pickup_documents (order_id, document_hash, document_last3)
  values (v_order.id, private.pickup_document_hash(v_order.id, v_digits), right(v_digits, 3))
  on conflict (order_id) do update
    set document_hash = excluded.document_hash, document_last3 = excluded.document_last3, updated_at = now();
  return jsonb_build_object('ok', true, 'document_last3', right(v_digits, 3));
end;
$$;


ALTER FUNCTION "public"."set_pickup_document"("p_order_id" "uuid", "p_document" "text") OWNER TO "postgres";

--
-- Name: set_stock_settings("uuid", integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_stock_settings"("p_product_id" "uuid", "p_low_stock_threshold" integer, "p_web_safety_stock" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product public.products;
begin
  perform private.require_staff(array['admin', 'warehouse']);
  if p_low_stock_threshold is null or p_low_stock_threshold < 0 or p_low_stock_threshold > 100000
     or p_web_safety_stock is null or p_web_safety_stock < 0 or p_web_safety_stock > 100000 then
    perform private.inventory_error('invalid_settings');
  end if;

  select * into v_product from public.products where id = p_product_id for update;
  if v_product.id is null then perform private.inventory_error('unknown_product'); end if;

  if v_product.low_stock_threshold = p_low_stock_threshold
     and v_product.web_safety_stock = p_web_safety_stock then
    return jsonb_build_object('ok', true, 'changed', false);
  end if;

  update public.products
  set low_stock_threshold = p_low_stock_threshold, web_safety_stock = p_web_safety_stock
  where id = p_product_id;

  insert into public.stock_settings_changes (
    product_id, old_low_stock_threshold, new_low_stock_threshold,
    old_web_safety_stock, new_web_safety_stock, changed_by
  ) values (
    p_product_id, v_product.low_stock_threshold, p_low_stock_threshold,
    v_product.web_safety_stock, p_web_safety_stock, auth.uid()
  );
  return jsonb_build_object('ok', true, 'changed', true);
end;
$$;


ALTER FUNCTION "public"."set_stock_settings"("p_product_id" "uuid", "p_low_stock_threshold" integer, "p_web_safety_stock" integer) OWNER TO "postgres";

--
-- Name: set_store_settings(double precision, double precision, "uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_store_settings"("p_lat" double precision, "p_lng" double precision, "p_zone_id" "uuid", "p_max_distance_m" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location jsonb;
  v_rows integer;
begin
  perform private.require_admin();
  if p_lat is null or p_lng is null or p_lat not between 5.95 and 6.55 or p_lng not between -75.75 and -75.15 then
    return jsonb_build_object('ok', false, 'error', 'location_outside_valley');
  end if;
  if p_zone_id is null or not exists (select 1 from public.delivery_zones where id = p_zone_id) then
    return jsonb_build_object('ok', false, 'error', 'unknown_zone');
  end if;
  if p_max_distance_m is null or p_max_distance_m not between 1000 and 50000 then
    return jsonb_build_object('ok', false, 'error', 'invalid_max_distance');
  end if;

  -- Six decimals (about 10 cm) are plenty for a store.
  v_location := jsonb_build_object('lat', round(p_lat::numeric, 6), 'lng', round(p_lng::numeric, 6));

  insert into public.app_settings (key, value) values
    ('store_location', v_location),
    ('store_zone_id', to_jsonb(p_zone_id::text)),
    ('delivery_max_distance_m', to_jsonb(p_max_distance_m))
  on conflict (key) do update set value = excluded.value
  where public.app_settings.value is distinct from excluded.value;

  get diagnostics v_rows = row_count;
  return jsonb_build_object('ok', true, 'changed', v_rows > 0);
end;
$$;


ALTER FUNCTION "public"."set_store_settings"("p_lat" double precision, "p_lng" double precision, "p_zone_id" "uuid", "p_max_distance_m" integer) OWNER TO "postgres";

--
-- Name: start_payment("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."start_payment"("p_order_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_detail text;
  v_block jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.orders where id = p_order_id and customer_id = v_uid
  ) then
    raise exception 'payment_order_not_found' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'payment_missing_idempotency_key' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.actions
    where idempotency_key = p_idempotency_key and user_id = v_uid and type = 'start_payment'
  ) then
    v_block := private.sales_block_at(
      'web',
      coalesce((select sale_zone_id from public.orders where id = p_order_id), private.store_zone_id()),
      now()
    );
    if v_block is not null then
      return jsonb_build_object('ok', false, 'error', 'sales_blocked', 'block', v_block);
    end if;
  end if;

  begin
    return private.create_payment_attempt(p_order_id, v_uid, p_idempotency_key);
  exception when sqlstate '22023' then
    get stacked diagnostics v_detail = pg_exception_detail;
    if sqlerrm = 'inventory_insufficient_stock' then
      return jsonb_build_object('ok', false, 'error', 'insufficient_stock', 'product_id', v_detail);
    end if;
    if sqlerrm in ('payment_in_progress', 'payment_order_not_payable') then
      return jsonb_build_object('ok', false, 'error', sqlerrm);
    end if;
    raise;
  end;
end;
$$;


ALTER FUNCTION "public"."start_payment"("p_order_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: store_payment_event("text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."store_payment_event"("p_checksum" "text", "p_source" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tx jsonb := p_payload #> '{data,transaction}';
  v_id uuid;
begin
  insert into public.payment_events (
    checksum, source, event_type, transaction_id, reference, status, amount_in_cents, currency, payload
  ) values (
    upper(p_checksum),
    p_source,
    coalesce(p_payload ->> 'event', 'unknown'),
    v_tx ->> 'id',
    v_tx ->> 'reference',
    v_tx ->> 'status',
    (v_tx ->> 'amount_in_cents')::bigint,
    v_tx ->> 'currency',
    p_payload
  )
  on conflict (checksum) do nothing
  returning id into v_id;

  if v_id is not null then
    return jsonb_build_object('event_id', v_id, 'created', true);
  end if;
  select id into v_id from public.payment_events where checksum = upper(p_checksum);
  return jsonb_build_object('event_id', v_id, 'created', false);
end;
$$;


ALTER FUNCTION "public"."store_payment_event"("p_checksum" "text", "p_source" "text", "p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: void_pos_sale("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."void_pos_sale"("p_order_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.orders;
  v_invoice public.invoices;
  v_item public.order_items;
  v_credit_note uuid;
  v_reason text := trim(coalesce(p_reason, ''));
begin
  if not private.has_staff_role(array['admin']) then
    raise exception 'pos_void_forbidden' using errcode = '42501';
  end if;
  if length(v_reason) not between 3 and 300 then
    return jsonb_build_object('ok', false, 'error', 'invalid_reason');
  end if;

  select * into v_order from public.orders where id = p_order_id and channel = 'pos' for update;
  if v_order.id is null then
    return jsonb_build_object('ok', false, 'error', 'sale_not_found');
  end if;
  if v_order.voided_at is not null then
    return jsonb_build_object('ok', true, 'already_voided', true);
  end if;

  -- The invoice is being issued: sent, or pending with its issue_invoice job
  -- still queued or running (same guard as mark_order_refunded, D-069).
  -- Voiding now could leave an invoice accepted right after, with no credit
  -- note. A pending invoice whose job already ended does not block the void
  -- forever; prepare_invoice refuses to send it once the sale is voided.
  select * into v_invoice from public.invoices where order_id = p_order_id for update;
  if v_invoice.status in ('pending', 'sent') and (
       v_invoice.status = 'sent'
       or exists (
         select 1 from public.actions a
         where a.idempotency_key = private.uuid_from_text('issue_invoice:' || p_order_id::text)
           and a.status in ('queued', 'processing')
       )
     ) then
    return jsonb_build_object('ok', false, 'error', 'invoice_in_progress', 'invoice_status', v_invoice.status);
  end if;

  for v_item in select * from public.order_items where order_id = p_order_id order by product_id
  loop
    perform private.lock_stock(v_item.product_id);
    insert into public.inventory_movements
      (product_id, movement_type, units, reference, reason, created_by, idempotency_key)
    values
      (v_item.product_id, 'return_in', v_item.base_units, p_order_id::text, 'Anulación POS: ' || v_reason,
       auth.uid(), private.uuid_from_text('pos_void:' || p_order_id || ':' || v_item.product_id));
  end loop;

  update public.orders
  set status = 'refunded', voided_at = now(), void_reason = v_reason, voided_by = auth.uid()
  where id = p_order_id;

  if v_invoice.status = 'accepted' then
    v_credit_note := public.request_credit_note(v_invoice.id, v_reason);
  end if;

  return jsonb_build_object('ok', true, 'already_voided', false, 'credit_note_id', v_credit_note);
end;
$$;


ALTER FUNCTION "public"."void_pos_sale"("p_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";

