--
-- Name: credit_notes_in_play; Type: VIEW; Schema: private; Owner: postgres
--

CREATE OR REPLACE VIEW "private"."credit_notes_in_play" WITH ("security_invoker"='true') AS
 SELECT "n"."id",
    "n"."reference_code",
    "n"."status",
    "n"."reason",
    "n"."kind",
    "n"."concept_code",
    "n"."last_error",
    "i"."factus_number" AS "invoice_number",
    "n"."created_at",
    "n"."attempts",
    "a"."status" AS "action_status",
    "a"."error" AS "action_error",
    (("n"."status" = 'rejected'::"public"."invoice_status") OR (NOT ("a"."status" IS DISTINCT FROM 'failed'::"public"."action_status"))) AS "needs_attention"
   FROM (("public"."credit_notes" "n"
     JOIN "public"."invoices" "i" ON (("i"."id" = "n"."invoice_id")))
     LEFT JOIN "public"."actions" "a" ON (("a"."idempotency_key" = "private"."uuid_from_text"(('issue_credit_note:'::"text" || ("n"."id")::"text")))))
  WHERE ("n"."status" <> 'accepted'::"public"."invoice_status");


ALTER VIEW "private"."credit_notes_in_play" OWNER TO "postgres";

--
-- Name: invoices_in_play; Type: VIEW; Schema: private; Owner: postgres
--

CREATE OR REPLACE VIEW "private"."invoices_in_play" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."order_id",
    "i"."reference_code",
    "i"."status",
    "i"."total_cop",
    "i"."last_error",
    "i"."dian_errors",
    "i"."response",
    "i"."attempts",
    "i"."updated_at",
    "o"."channel",
    "a"."status" AS "action_status",
    "a"."error" AS "action_error",
    (("i"."status" = 'rejected'::"public"."invoice_status") OR (NOT ("a"."status" IS DISTINCT FROM 'failed'::"public"."action_status"))) AS "needs_attention"
   FROM (("public"."invoices" "i"
     JOIN "public"."orders" "o" ON (("o"."id" = "i"."order_id")))
     LEFT JOIN "public"."actions" "a" ON (("a"."idempotency_key" = "private"."uuid_from_text"(('issue_invoice:'::"text" || ("i"."order_id")::"text")))))
  WHERE (("i"."status" <> 'accepted'::"public"."invoice_status") AND ("o"."voided_at" IS NULL) AND (NOT "o"."needs_refund"));


ALTER VIEW "private"."invoices_in_play" OWNER TO "postgres";

