--
-- Name: pickups_needing_attention; Type: VIEW; Schema: private; Owner: postgres
--

CREATE OR REPLACE VIEW "private"."pickups_needing_attention" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "order_id",
    "o"."status",
    "c"."full_name" AS "customer_name",
    "o"."paid_at",
    "o"."total_cop",
    "o"."return_choice_defaulted",
        CASE
            WHEN "private"."pickup_locked"("d"."failed_attempts") THEN 'locked'::"text"
            ELSE 'missing_document'::"text"
        END AS "reason",
    COALESCE("d"."failed_attempts", 0) AS "failed_attempts",
    (("d"."document_hash" IS NULL) AND ("c"."document_type" IS DISTINCT FROM 'nit'::"public"."document_type")) AS "missing_document"
   FROM (("public"."orders" "o"
     JOIN "public"."customers" "c" ON (("c"."id" = "o"."customer_id")))
     LEFT JOIN "private"."order_pickup_documents" "d" ON (("d"."order_id" = "o"."id")))
  WHERE (("o"."channel" = 'web'::"public"."order_channel") AND ("o"."fulfillment" = 'pickup'::"public"."fulfillment_method") AND (NOT "o"."needs_refund") AND ("o"."status" = ANY (ARRAY['paid'::"public"."order_status", 'preparing'::"public"."order_status"])) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."pickup_confirmations" "pc"
          WHERE ("pc"."order_id" = "o"."id")))) AND ("private"."pickup_locked"("d"."failed_attempts") OR (("d"."document_hash" IS NULL) AND ("c"."document_type" IS DISTINCT FROM 'nit'::"public"."document_type"))));


ALTER VIEW "private"."pickups_needing_attention" OWNER TO "postgres";

