-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."inventory_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "product_id" "uuid" NOT NULL,
    "movement_type" "public"."inventory_movement_type" NOT NULL,
    "units" integer NOT NULL,
    "reason" "text",
    "reference" "text",
    "reservation_id" "uuid",
    "created_by" "uuid",
    "idempotency_key" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "inventory_movements_reason_check" CHECK (("length"(TRIM(BOTH FROM "reason")) > 0)),
    CONSTRAINT "inventory_movements_reference_check" CHECK (("length"(TRIM(BOTH FROM "reference")) > 0)),
    CONSTRAINT "inventory_movements_requires_reason" CHECK ((("movement_type" <> ALL (ARRAY['adjustment'::"public"."inventory_movement_type", 'waste'::"public"."inventory_movement_type"])) OR ("reason" IS NOT NULL))),
    CONSTRAINT "inventory_movements_requires_reference" CHECK ((("movement_type" <> 'purchase_in'::"public"."inventory_movement_type") OR ("reference" IS NOT NULL))),
    CONSTRAINT "inventory_movements_sign_check" CHECK (
CASE "movement_type"
    WHEN 'purchase_in'::"public"."inventory_movement_type" THEN ("units" > 0)
    WHEN 'return_in'::"public"."inventory_movement_type" THEN ("units" > 0)
    WHEN 'reservation'::"public"."inventory_movement_type" THEN ("units" > 0)
    WHEN 'web_sale'::"public"."inventory_movement_type" THEN ("units" < 0)
    WHEN 'pos_sale'::"public"."inventory_movement_type" THEN ("units" < 0)
    WHEN 'waste'::"public"."inventory_movement_type" THEN ("units" < 0)
    WHEN 'reservation_release'::"public"."inventory_movement_type" THEN ("units" < 0)
    WHEN 'adjustment'::"public"."inventory_movement_type" THEN true
    ELSE NULL::boolean
END),
    CONSTRAINT "inventory_movements_units_check" CHECK (("units" <> 0))
);


