CREATE POLICY "product_prices: admin updates" ON "public"."product_prices" FOR UPDATE TO "authenticated" USING (( SELECT "private"."has_staff_role"(ARRAY['admin'::"text"]) AS "has_staff_role")) WITH CHECK (( SELECT "private"."has_staff_role"(ARRAY['admin'::"text"]) AS "has_staff_role"));


--
-- Name: product_prices product_prices: read when list and product are visible; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "product_prices: read when list and product are visible" ON "public"."product_prices" FOR SELECT TO "authenticated", "anon" USING (((EXISTS ( SELECT 1
   FROM "public"."price_lists" "pl"
  WHERE ("pl"."id" = "product_prices"."price_list_id"))) AND (EXISTS ( SELECT 1
   FROM "public"."products" "p"
  WHERE ("p"."id" = "product_prices"."product_id")))));


